function getChamberPatterns(chamber) {
  const patterns = [];
  const stars = [
    ...chamber.chinh_tinh.map(s => s.name.toUpperCase()),
    ...chamber.cat_tinh.map(s => s.name.toUpperCase()),
    ...chamber.hung_tinh.map(s => s.name.toUpperCase())
  ];
  const isVcd = chamber.chinh_tinh.length === 0;
  
  // 1. Check Tử Phủ Vũ Tướng
  const tpvtCount = stars.filter(s => ["TỬ VI", "THIÊN PHỦ", "VŨ KHÚC", "THIÊN TƯỚNG"].includes(s)).length;
  if (tpvtCount >= 2) {
    patterns.push({
      name: "Tử Phủ Vũ Tướng Cách",
      desc: "Cách cục của người lãnh đạo, quản lý. Chủ về tài lộc vững chắc, có vị thế xã hội cao, được người khác nể trọng kính phục."
    });
  }
  
  // 2. Check Sát Phá Tham
  const sptCount = stars.filter(s => ["THẤT SÁT", "PHÁ QUÂN", "THAM LANG"].includes(s)).length;
  if (sptCount >= 1 && (chamber.id === "menh" || sptCount >= 2)) {
    patterns.push({
      name: "Sát Phá Tham Cách",
      desc: "Cách cục biến động lớn. Đương số là người dũng cảm xông pha, dám thay đổi bứt phá, tuy nhiên cần đề phòng thăng trầm sóng gió."
    });
  }
  
  // 3. Check Cơ Nguyệt Đồng Lương
  const cndlCount = stars.filter(s => ["THIÊN CƠ", "THÁI ÂM", "THIÊN ĐỒNG", "THIÊN LƯƠNG"].includes(s)).length;
  if (cndlCount >= 2) {
    patterns.push({
      name: "Cơ Nguyệt Đồng Lương Cách",
      desc: "Cách cục của người làm công chức, mưu sĩ, chuyên môn kỹ thuật hoặc giáo dục y tế. Cuộc sống bình hòa ổn định, mưu cầu danh lộc cát lợi."
    });
  }
  
  // 4. Check Cự Nhật
  const cnCount = stars.filter(s => ["CỰ MÔN", "THÁI DƯƠNG"].includes(s)).length;
  if (cnCount >= 1 && (chamber.id === "menh" || cnCount >= 2)) {
    patterns.push({
      name: "Cự Nhật Đồng Cung Cách",
      desc: "Cách cục có khiếu biện luận, ngoại giao, nghiên cứu hoặc làm việc với người nước ngoài. Danh tiếng lan tỏa chiêu tài."
    });
  }
  
  // 5. Check VCD đắc Không Vong
  if (isVcd) {
    const hasTuan = chamber.tuan_triet && chamber.tuan_triet.includes("Tuần");
    const hasTriet = chamber.tuan_triet && chamber.tuan_triet.includes("Triệt");
    const hasKhong = stars.includes("ĐỊA KHÔNG");
    const hasKiep = stars.includes("ĐỊA KIẾP");
    if ((hasTuan || hasTriet) && (hasKhong || hasKiep)) {
      patterns.push({
        name: "Vô Chính Diệu đắc Tam Không",
        desc: "Cung vị không có chính tinh nhưng đắc Không Vong án ngữ, chủ về hoạnh phát bất ngờ, tư duy độc đáo xuất thần."
      });
    }
  }
  
  // 6. Check Thạch Trung Ẩn Ngọc
  if (stars.includes("CỰ MÔN") && ["Tý", "Ngọ"].includes(chamber.chi)) {
    patterns.push({
      name: "Thạch Trung Ẩn Ngọc Cách",
      desc: "Cự Môn tại Tý/Ngọ chủ về ngọc ẩn trong đá. Đương số thuở trẻ cần mài giũa học hành gian khổ, trung vận phát đạt rực rỡ nhờ tài năng trí tuệ."
    });
  }
  
  // 7. Check Nhật Xuất Phù Tang
  if (stars.includes("THÁI DƯƠNG") && chamber.chi === "Mão") {
    patterns.push({
      name: "Nhật Xuất Phù Tang Cách",
      desc: "Mặt trời mọc ở phương đông cát lợi rực rỡ, mang lại sự thông tuệ, danh tiếng vang dội và sự nghiệp hanh thông từ rất sớm."
    });
  }
  
  return patterns;
}

function getPhiTinhExplanation(chamber) {
  const can = chamber.can;
  const transformations = phiTinhMap[can];
  if (!transformations) return "";
  
  let html = `<div style="font-size: 0.82rem; line-height: 1.5; color: var(--color-text-secondary); margin-top: 4px;">`;
  html += `Cung **${chamber.name}** có Thiên Can **${can}**, phát động khí số Tứ Hóa bay sang các cung vị chứa chính tinh tương ứng: <br/>`;
  
  for (const [transName, starName] of Object.entries(transformations)) {
    const targetChamber = tuviData.chambers.find(c => {
      return [
        ...c.chinh_tinh,
        ...c.cat_tinh,
        ...c.hung_tinh
      ].some(s => s.name.toUpperCase() === starName.toUpperCase());
    });
    
    if (targetChamber) {
      const transKey = transName === "Lộc" ? "loc" : (transName === "Quyền" ? "quyen" : (transName === "Khoa" ? "khoa" : "ky"));
      const colorMap = {
        "loc": "#10b981",
        "quyen": "#f59e0b",
        "khoa": "#3b82f6",
        "ky": "#ef4444"
      };
      
      let meaning = "";
      if (transName === "Lộc") {
        meaning = `mang lại may mắn, cát lành, nhân quả hanh thông cát lợi sang cung **${targetChamber.name}**.`;
      } else if (transName === "Quyền") {
        meaning = `mang lại uy thế quyền lực, sự cạnh tranh nỗ lực hành động quyết tâm sang cung **${targetChamber.name}**.`;
      } else if (transName === "Khoa") {
        meaning = `mang lại tri thức học thức khoa danh, quý nhân nâng đỡ hoặc sự hóa giải tai ương sang cung **${targetChamber.name}**.`;
      } else if (transName === "Kỵ") {
        meaning = `mang lại nợ nần nhân quả, lo toan áp lực, sự cản trở thị phi hoặc duyên nợ khó dứt tại cung **${targetChamber.name}**.`;
      }
      
      html += `• Hóa **${transName}** (${starName}) &rarr; <span style="color: ${colorMap[transKey]}; font-weight: bold;">${targetChamber.name}</span>: ${meaning}<br/>`;
    }
  }
  
  html += `</div>`;
  return html;
}

function toggleThaiCuc(id) {
  if (activeThaiCucId === id) {
    activeThaiCucId = null;
  } else {
    activeThaiCucId = id;
  }
  
  // Re-render grid to update names
  renderGrid();
  
  // Keep the card active on grid
  const cards = document.querySelectorAll(".chamber-card");
  cards.forEach(card => {
    card.classList.remove("active", "connected-tam-hop", "connected-xung-chieu", "connected-nhi-hop");
  });
  
  const activeCard = document.getElementById(`card-${id}`);
  if (activeCard) {
    activeCard.classList.add("active");
    
    // Highlight connected cards
    const conn = connectionMap[id];
    if (conn) {
      conn.tam_hop.forEach(tId => {
        const cCard = document.getElementById(`card-${tId}`);
        if (cCard) cCard.classList.add("connected-tam-hop");
      });
      const xcCard = document.getElementById(`card-${conn.xung_chieu}`);
      if (xcCard) xcCard.classList.add("connected-xung-chieu");
      const nhCard = document.getElementById(`card-${conn.nhi_hop}`);
      if (nhCard) nhCard.classList.add("connected-nhi-hop");
    }
  }
  
  // Redraw lines
  drawConnectingLines(id);
  drawPhiTinhLines(id);
  
  // Re-render details to update button text
  renderChamberDetails(id);
}

function drawPhiTinhLines(activeId) {
  const svg = document.querySelector(".svg-overlay");
  ensureSvgDefs(svg);
  
  const wrapper = document.querySelector(".tuvi-grid-wrapper");
  const wrapperRect = wrapper.getBoundingClientRect();
  
  function getCenter(cardId) {
    const card = document.getElementById(`card-${cardId}`);
    if (!card) return null;
    const rect = card.getBoundingClientRect();
    return {
      x: rect.left - wrapperRect.left + rect.width / 2,
      y: rect.top - wrapperRect.top + rect.height / 2
    };
  }
  
  const activeCenter = getCenter(activeId);
  if (!activeCenter) return;
  
  const chamber = tuviData.chambers.find(c => c.id === activeId);
  if (!chamber || !chamber.can) return;
  
  const can = chamber.can;
  const transformations = phiTinhMap[can];
  if (!transformations) return;
  
  for (const [transName, starName] of Object.entries(transformations)) {
    const targetChamber = tuviData.chambers.find(c => {
      return [
        ...c.chinh_tinh,
        ...c.cat_tinh,
        ...c.hung_tinh
      ].some(s => s.name.toUpperCase() === starName.toUpperCase());
    });
    
    if (targetChamber) {
      const targetCenter = getCenter(targetChamber.id);
      if (targetCenter) {
        const transKey = transName === "Lộc" ? "loc" : (transName === "Quyền" ? "quyen" : (transName === "Khoa" ? "khoa" : "ky"));
        const colorMap = {
          "loc": "#059669",
          "quyen": "#d97706",
          "khoa": "#0284c7",
          "ky": "#dc2626"
        };
        const line = document.createElementNS("http://www.w3.org/2000/svg", "line");
        line.setAttribute("x1", activeCenter.x);
        line.setAttribute("y1", activeCenter.y);
        line.setAttribute("x2", targetCenter.x);
        line.setAttribute("y2", targetCenter.y);
        line.setAttribute("stroke", colorMap[transKey]);
        line.setAttribute("stroke-width", "2");
        line.setAttribute("stroke-dasharray", "4,4");
        line.setAttribute("marker-end", `url(#arrow-${transKey})`);
        line.setAttribute("class", `phi-tinh-line phi-${transKey}`);
        svg.appendChild(line);
      }
    }
  }
}

