// Helper to map Vietnamese element names to English CSS class keys (handling accents)
function getElementKey(elementName) {
  if (!elementName) return "";
  const map = {
    "Mộc": "moc",
    "Hỏa": "hoa",
    "Thổ": "tho",
    "Kim": "kim",
    "Thủy": "thuy"
  };
  const trimmed = elementName.trim();
  return map[trimmed] || trimmed.toLowerCase();
}

