    "Thai Phụ": "Cát tinh chủ về bằng cấp, sắc phong, khen thưởng, sự tôn vinh trong học tập hoặc công danh.",
    "Phong Cáo": "Cát tinh chủ về khen thưởng, danh dự, phong chức, công nhận công trạng và sự tự hào cá nhân.",
    "Nguyệt Đức": "Cát tinh chủ về đức hạnh, sự từ bi, hòa nhã, giải trừ tai ách và mang lại nhân duyên lành.",
    "Thiên Quan": "Cát tinh chủ về sự từ thiện, tu hành, tính tình hiền hậu, được mọi người kính trọng và có số hưởng an nhàn.",
