    "Hoa Cái": "Cát tinh chủ về vẻ ngoài thanh lịch, oai vệ, năng khiếu nghệ thuật độc đáo, sự cô độc của người tài hoa và xu hướng tâm linh sâu sắc.",
    "Quốc Ấn": "Cát tinh chủ về quyền lực, chức vụ, con dấu, sự sắc phong và uy tín chính thức trong công việc.",
