      "text": "<b>Đặc tính Cát Tinh:</b> Văn Xương chủ về học thuật tri thức khoa bảng.<br><b>Luận giải:</b> Sự hiện diện của Văn Xương mang lại luồng cát khí tri thức, học hỏi nhạy bén nhạy cảm, giúp đương số đỗ đạt cao khoa bảng hanh thông và có uy tín học vấn tốt lành tại khía cạnh Cung Phúc Đức.",
