function toggleAccordion(id) {
  const content = document.getElementById("content-" + id);
  const arrow = document.getElementById("arrow-" + id);
  if (!content) return;
  
  if (content.style.display === "none" || content.style.display === "") {
    content.style.display = "block";
    if (arrow) arrow.innerHTML = "Thu gọn ▴";
  } else {
    content.style.display = "none";
    if (arrow) arrow.innerHTML = "Xem chi tiết ▾";
  }
}

// Switch between Main Tabs (Lá Số vs Bản Luận Giải vs Bát Tự vs Dịch Lý vs Vận Hạn 12 Tháng)
let currentDedicatedMonth = 1;

function switchMainTab(tabId) {
  if (!hasCalculated && tabId !== 'laso') {
    alert("Vui lòng nhập họ tên, ngày tháng năm sinh tại tab 'LÁ SỐ TỬ VI & BÁT TRẬN' và bấm 'LẬP THÀNH LÁ SỐ' trước để xem đầy đủ luận giải nhé!");
    return;
  }
  const btnLaso = document.getElementById("btn-main-tab-laso");
  const btnLuangiai = document.getElementById("btn-main-tab-luangiai");
  const btnBatu = document.getElementById("btn-main-tab-batu");
  const btnTriethoc = document.getElementById("btn-main-tab-triethoc");
  const btnThangam = document.getElementById("btn-main-tab-thangam");

  const contentLaso = document.getElementById("main-tab-content-laso");
  const contentLuangiai = document.getElementById("main-tab-content-luangiai");
  const contentBatu = document.getElementById("main-tab-content-batu");
  const contentTriethoc = document.getElementById("main-tab-content-triethoc");
  const contentThangam = document.getElementById("main-tab-content-thangam");
  
  [btnLaso, btnLuangiai, btnBatu, btnTriethoc, btnThangam].forEach(b => { if (b) b.classList.remove("active"); });
  [contentLaso, contentLuangiai, contentBatu, contentTriethoc, contentThangam].forEach(c => { if (c) c.style.display = "none"; });
  
  if (tabId === 'laso') {
    if (btnLaso) btnLaso.classList.add("active");
    if (contentLaso) contentLaso.style.display = "block";
    const activeCard = document.querySelector(".chamber-card.active");
    if (activeCard) {
      setTimeout(() => {
        drawConnectingLines(activeCard.dataset.id);
        drawPhiTinhLines(activeCard.dataset.id);
      }, 50);
    }
  } else if (tabId === 'luangiai') {
    if (btnLuangiai) btnLuangiai.classList.add("active");
    if (contentLuangiai) contentLuangiai.style.display = "block";
    const svgOverlay = document.getElementById("svg-connections");
    if (svgOverlay) svgOverlay.innerHTML = "";
  } else if (tabId === 'batu') {
    if (btnBatu) btnBatu.classList.add("active");
    if (contentBatu) contentBatu.style.display = "block";
    renderBatuDedicatedTab();
    const svgOverlay = document.getElementById("svg-connections");
    if (svgOverlay) svgOverlay.innerHTML = "";
  } else if (tabId === 'triethoc') {
    if (btnTriethoc) btnTriethoc.classList.add("active");
    if (contentTriethoc) contentTriethoc.style.display = "block";
    const svgOverlay = document.getElementById("svg-connections");
    if (svgOverlay) svgOverlay.innerHTML = "";
  } else if (tabId === 'thangam') {
    if (btnThangam) btnThangam.classList.add("active");
    if (contentThangam) contentThangam.style.display = "block";
    renderDedicatedMonthlyTab(currentDedicatedMonth || 1);
    const svgOverlay = document.getElementById("svg-connections");
    if (svgOverlay) svgOverlay.innerHTML = "";
  }
}

// Render dynamic Bát Tự Tab for ANY chart
function renderBatuDedicatedTab() {
  const container = document.getElementById("batu-dedicated-table-container");
  if (!container) return;
  
  const bazi = tuviData.bazi;
  if (!bazi || !bazi.pillars) {
    container.innerHTML = "<p style='color: var(--color-text-secondary); font-style: italic;'>Vui lòng nhập thông tin lập lá số để xem bảng Tứ Trụ chi tiết.</p>";
    return;
  }
  
  const pillars = bazi.pillars;
  const pKeys = ["year", "month", "day", "hour"];
  const pLabels = {
    "year": "Trụ Năm (Tổ Tiên / Căn Cơ)",
    "month": "Trụ Tháng (Cha Mẹ / Xã Hội)",
    "day": "Trụ Ngày (Bản Thân / Phối Ngẫu)",
    "hour": "Trụ Giờ (Con Cái / Hậu Vận)"
  };
  
  let html = `
    <table class="data-table" style="width: 100%; border-collapse: collapse; margin-top: 10px; font-size: 0.88rem; background: #ffffff; border-radius: 8px; overflow: hidden; box-shadow: 0 2px 8px rgba(180, 140, 50, 0.08);">
      <thead>
        <tr style="background: var(--color-gold-light); color: #78350f;">
          <th style="padding: 10px 12px; border: 1px solid #cbd5e1; text-align: left;">Thuộc Tính</th>
  `;
  
  pKeys.forEach(k => {
    html += `<th style="padding: 10px 12px; border: 1px solid #cbd5e1; text-align: center; font-weight: bold;">${pLabels[k]}</th>`;
  });
  
  html += `</tr></thead><tbody>`;
  
  // Row 1: Thiên Can
  html += `<tr><td style="padding: 8px 12px; border: 1px solid #cbd5e1; font-weight: bold; background: #f8fafc;">Thiên Can</td>`;
  pKeys.forEach(k => {
    const p = pillars[k] || {};
    const isDay = (k === "day");
    const canColor = p.can_elem === "Mộc" ? "var(--color-moc)" : (p.can_elem === "Hỏa" ? "var(--color-hoa)" : (p.can_elem === "Thổ" ? "var(--color-tho)" : (p.can_elem === "Kim" ? "var(--color-kim)" : "var(--color-thuy)")));
    html += `<td style="padding: 8px 12px; border: 1px solid #cbd5e1; text-align: center; font-size: 1.15rem; font-weight: 800; color: ${canColor};">
      ${p.can || ""} <span style="font-size: 0.75rem; font-weight: normal; color: #64748b;">(${p.can_polarity || ""} ${p.can_elem || ""})</span>
      ${isDay ? '<br><span style="font-size: 0.72rem; background: var(--color-gold-light); color: #78350f; padding: 2px 6px; border-radius: 4px; font-weight: bold;">NHẬT CHỦ</span>' : ''}
    </td>`;
  });
  html += `</tr>`;
  
  // Row 2: Thập Thần Can
  html += `<tr><td style="padding: 8px 12px; border: 1px solid #cbd5e1; font-weight: bold; background: #f8fafc;">Thập Thần Can</td>`;
  pKeys.forEach(k => {
    const p = pillars[k] || {};
    html += `<td style="padding: 8px 12px; border: 1px solid #cbd5e1; text-align: center; font-weight: 700; color: var(--color-cinnabar);">
      ${p.can_ten_god || ""}
    </td>`;
  });
  html += `</tr>`;
  
  // Row 3: Địa Chi
  html += `<tr><td style="padding: 8px 12px; border: 1px solid #cbd5e1; font-weight: bold; background: #f8fafc;">Địa Chi</td>`;
  pKeys.forEach(k => {
    const p = pillars[k] || {};
    const chiColor = p.chi_elem === "Mộc" ? "var(--color-moc)" : (p.chi_elem === "Hỏa" ? "var(--color-hoa)" : (p.chi_elem === "Thổ" ? "var(--color-tho)" : (p.chi_elem === "Kim" ? "var(--color-kim)" : "var(--color-thuy)")));
    html += `<td style="padding: 8px 12px; border: 1px solid #cbd5e1; text-align: center; font-size: 1.15rem; font-weight: 800; color: ${chiColor};">
      ${p.chi || ""} <span style="font-size: 0.75rem; font-weight: normal; color: #64748b;">(${p.chi_polarity || ""} ${p.chi_elem || ""})</span>
    </td>`;
  });
  html += `</tr>`;
  
  // Row 4: Tàng Can Chi Tiết
  html += `<tr><td style="padding: 8px 12px; border: 1px solid #cbd5e1; font-weight: bold; background: #f8fafc;">Tàng Can trong Chi</td>`;
  pKeys.forEach(k => {
    const p = pillars[k] || {};
    const stems = p.hidden_stems_detail || [];
    let stemsHtml = stems.map(s => `<div><strong>${s.can}</strong> (${s.elem}) - <span style="color: var(--color-cinnabar); font-weight: 600;">${s.ten_god}</span> [${s.type} ${Math.round(s.ratio * 100)}%]</div>`).join("");
    if (!stemsHtml && p.hidden_can) {
      stemsHtml = `<div><strong>${p.hidden_can}</strong> (${p.hidden_can_elem || ""}) - ${p.hidden_ten_god || ""}</div>`;
    }
    html += `<td style="padding: 8px 12px; border: 1px solid #cbd5e1; font-size: 0.8rem; line-height: 1.4;">${stemsHtml || "Chưa rõ"}</td>`;
  });
  html += `</tr>`;
  
  html += `</tbody></table>`;
  
  // Additional info box
  html += `
    <div style="margin-top: 12px; padding: 12px 16px; background: #fbf9f4; border: 1px solid var(--color-border); border-radius: 8px; font-size: 0.85rem; line-height: 1.6;">
      <strong>• Thai Cung:</strong> ${pillars.thai_cung ? `${pillars.thai_cung.can} ${pillars.thai_cung.chi} (${pillars.thai_cung.can_ten_god})` : "Bính Tý (Thiên Tài)"} &nbsp;&nbsp;|&nbsp;&nbsp;
      <strong>• Mệnh Cung:</strong> ${pillars.menh_cung ? `${pillars.menh_cung.can} ${pillars.menh_cung.chi} (${pillars.menh_cung.can_ten_god})` : "Kỷ Sửu (Chính Quan)"} &nbsp;&nbsp;|&nbsp;&nbsp;
      <strong>• Thai Tức:</strong> ${pillars.thai_tuc ? `${pillars.thai_tuc.can} ${pillars.thai_tuc.chi} (${pillars.thai_tuc.can_ten_god})` : "Đinh Sửu (Chính Tài)"}
    </div>
  `;
  container.innerHTML = html;

  // Dynamically update Section 2: Luận Giải Nhật Chủ
  const secNhatChu = document.getElementById("batu-section-nhat-chu");
  if (secNhatChu) {
    const dm = bazi.day_master || (pillars.day ? pillars.day.can : "Nhâm");
    const dmElem = bazi.day_master_elem || (pillars.day ? pillars.day.can_elem : "Thủy");
    const vs = bazi.vuong_suy || "Được sinh (Tướng)";
    const monthChi = pillars.month ? pillars.month.chi : "Dậu";
    
    secNhatChu.innerHTML = `
      <article class="essay-card">
        <div class="essay-header">
          <div class="essay-icon">🌊⚡</div>
          <div>
            <h2 class="essay-title">2. LUẬN GIẢI NHẬT CHỦ (${dm.toUpperCase()} ${dmElem.toUpperCase()}) & NGŨ HÀNH CỤC DIỆN</h2>
            <div style="font-size: 0.85rem; color: var(--color-gold); font-weight: 600;">Nhật Chủ: ${dm} (${dmElem}) • Trạng Thái: ${vs} • Lệnh Tháng: ${monthChi}</div>
          </div>
        </div>
        <div class="essay-content">
          <p>
            • <strong>Bản Tính Nhật Chủ ${dm} ${dmElem}:</strong> Trong Bát Tự Tử Bình, Can Ngày tượng trưng cho bản thể cốt lõi, tâm thức và ý chí của đương số <strong>${tuviData.personal_info.name}</strong>. Người mang Nhật Chủ ${dm} (${dmElem}) sở hữu tư duy sắc bén, tính khí kiên định và khả năng học hỏi thích ứng linh hoạt với thời cuộc.
          </p>
          <p>
            • <strong>Tương tác với Lệnh Tháng (${monthChi}):</strong> Sinh vào tháng ${monthChi}, bản mệnh được đánh giá ở thế: <em>${vs}</em>. Điều này phản ánh nguồn nội lực và sức sống tiềm tàng bên trong, giúp đương số vững vàng vượt qua các đợt sóng gió thử thách trong đời.
          </p>
          <p>
            • <strong>Đánh Giá Cường Nhược:</strong> Khí số ngũ hành cân bằng tạo điều kiện thuận lợi để đương số phát huy trọn vẹn sở trường, biến tri thức thành năng lực điều hành thực tiễn.
          </p>
          <div class="essay-quote">
            "Trích Thiên Tủy: 'Ngũ hành lưu chuyển, âm dương tương thôi. Đắc thời đắc vị thì vạn sự hanh thông, tu dưỡng đức hạnh thì phúc báu bền lâu!'"
          </div>
        </div>
      </article>
    `;
  }

  // Section 3: Thập Thần Bát Tự
  const secThapThan = document.getElementById("batu-section-thap-than");
  if (secThapThan) {
    const yGod = pillars.year ? pillars.year.can_ten_god : "Thương Quan";
    const mGod = pillars.month ? pillars.month.can_ten_god : "Thương Quan";
    const hGod = pillars.hour ? pillars.hour.can_ten_god : "Chính Tài";
    
    secThapThan.innerHTML = `
      <article class="essay-card">
        <div class="essay-header">
          <div class="essay-icon">👑💡</div>
          <div>
            <h2 class="essay-title">3. THẬP THẦN BÁT TỰ & CĂN KHÍ TÂM TÍNH</h2>
            <div style="font-size: 0.85rem; color: var(--color-gold); font-weight: 600;">Trụ Năm: ${yGod} • Trụ Tháng: ${mGod} • Trụ Giờ: ${hGod}</div>
          </div>
        </div>
        <div class="essay-content">
          <p>
            • <strong>Trụ Năm (${yGod}):</strong> Tượng trưng cho phúc ấm tổ tiên và nền tảng ấu thơ. Ngôi sao ${yGod} ngụ tại đây nhắc nhở đương số luôn ghi nhớ cội nguồn, phát huy truyền thống hiếu học gia phong.
          </p>
          <p>
            • <strong>Trụ Tháng (${mGod}):</strong> Ngôi sao chủ quản chí hướng thanh xuân và phương thức tạo dựng sự nghiệp. ${mGod} thể hiện phong cách hành sự độc lập, giàu tính sáng tạo, không chịu gò bó theo khuôn mẫu rập khuôn.
          </p>
          <p>
            • <strong>Trụ Giờ (${hGod}):</strong> Ngôi sao chủ về hậu vận và thế hệ tương lai. Sự hiện diện của ${hGod} tại trụ giờ báo hiệu hậu vận sung túc, con cái hiếu thảo thành tài.
          </p>
        </div>
      </article>
    `;
  }

  // Section 4: Tương Tác Hình Xung Hợp Hại
  const secTuongTac = document.getElementById("batu-section-tuong-tac");
  if (secTuongTac) {
    const yCan = pillars.year ? pillars.year.can : "";
    const mCan = pillars.month ? pillars.month.can : "";
    const dCan = pillars.day ? pillars.day.can : "";
    const hCan = pillars.hour ? pillars.hour.can : "";
    
    const yChi = pillars.year ? pillars.year.chi : "";
    const mChi = pillars.month ? pillars.month.chi : "";
    const dChi = pillars.day ? pillars.day.chi : "";
    const hChi = pillars.hour ? pillars.hour.chi : "";

    secTuongTac.innerHTML = `
      <article class="essay-card">
        <div class="essay-header">
          <div class="essay-icon">🔗⚡</div>
          <div>
            <h2 class="essay-title">4. CÁC MỐI LIÊN KẾT TƯƠNG TÁC GIỮA CÁC TRỤ (HÌNH - XUNG - HỢP - HẠI)</h2>
            <div style="font-size: 0.85rem; color: var(--color-gold); font-weight: 600;">Thiên Can: ${yCan} - ${mCan} - ${dCan} - ${hCan} • Địa Chi: ${yChi} - ${mChi} - ${dChi} - ${hChi}</div>
          </div>
        </div>
        <div class="essay-content">
          <p>
            • <strong>Tương tác Thiên Can:</strong> Bốn thiên can (${yCan}, ${mCan}, ${dCan}, ${hCan}) tương tác phối hợp âm dương hòa hợp, tạo nên thế cân bằng giúp đương số luôn giữ được sự điềm tĩnh trước mọi biến cố.
          </p>
          <p>
            • <strong>Tương tác Địa Chi:</strong> Bốn địa chi (${yChi}, ${mChi}, ${dChi}, ${hChi}) tạo nên mạng lưới tương liên mật thiết giữa các thế hệ: từ tổ tiên (trụ năm) qua phụ mẫu (trụ tháng) đến bản thân (trụ ngày) và con cái (trụ giờ).
          </p>
          <p>
            • <strong>Lời Khuyên Hóa Giải:</strong> Mọi sự xung khắc nhẹ nếu có giữa các chi đều được hóa giải trọn vẹn thông qua lối sống đức độ, sự thấu hiểu và lòng bao dung trong gia đình.
          </p>
        </div>
      </article>
    `;
  }

  // Section 5: Mối Tương Quan Bát Tự & Tử Vi
  const secTuviTuTru = document.getElementById("batu-section-tuvi-tu-tru");
  if (secTuviTuTru) {
    secTuviTuTru.innerHTML = `
      <article class="essay-card">
        <div class="essay-header">
          <div class="essay-icon">☯☸</div>
          <div>
            <h2 class="essay-title">5. MỐI LIÊN KẾT TƯƠNG HỖ MẬT THIẾT GIỮA BÁT TỰ VÀ LÁ SỐ TỬ VI</h2>
            <div style="font-size: 0.85rem; color: var(--color-gold); font-weight: 600;">Sự Trùng Khớp Kỳ Diệu Giữa Tiên Thiên Cốt Cách & Hậu Thiên Tinh Bàn</div>
          </div>
        </div>
        <div class="essay-content">
          <div class="essay-quote">
            "Bát Tự là Cốt Cách Tiên Thiên do Trời phú — Tử Vi là Bàn Cờ Hậu Thiên ứng biến theo Thời Gian. Cả hai cùng hội tụ về bản mệnh ${tuviData.personal_info.name} hoàn toàn thống nhất!"
          </div>
          <p>
            • <strong>Trụ Năm <---> Cung Phụ Mẫu & Phúc Đức:</strong> Thể hiện cội nguồn gia tộc, âm đức tổ tiên tương trợ đắc lực cho con cháu phát triển.
          </p>
          <p>
            • <strong>Trụ Tháng <---> Cung Quan Lộc:</strong> Định hướng sự nghiệp chuyên môn, tư duy giải pháp công nghệ và năng lực hoạch định chiến lược.
          </p>
          <p>
            • <strong>Trụ Ngày <---> Cung Mệnh & Cung Phu Thê:</strong> Bản lĩnh cá nhân hòa quyện cùng duyên nợ vợ chồng, tạo lập mái ấm gia đình hạnh phúc.
          </p>
          <p>
            • <strong>Trụ Giờ <---> Cung Tử Tức & Điền Trạch:</strong> Hậu vận con cái vinh hiển, cơ ngơi bất động sản ngày càng khang trang vững chắc.
          </p>
        </div>
      </article>
    `;
  }

  // Section 6: Dụng Thần & Lời Khuyên Hành Mệnh
  const secDungThan = document.getElementById("batu-section-dung-than");
  if (secDungThan) {
    const dmElem = bazi.day_master_elem || (pillars.day ? pillars.day.can_elem : "Thủy");
    secDungThan.innerHTML = `
      <article class="essay-card">
        <div class="essay-header">
          <div class="essay-icon">🧭✨</div>
          <div>
            <h2 class="essay-title">6. DỤNG THẦN, HỶ THẦN & ĐỊNH HƯỚNG HÀNH MỆNH</h2>
            <div style="font-size: 0.85rem; color: var(--color-gold); font-weight: 600;">Phong Thủy Cân Bằng • Hướng Đi Tối Ưu • Kích Hoạt Tài Lộc</div>
          </div>
        </div>
        <div class="essay-content">
          <p>
            • <strong>Nguyên Tắc Dụng Thần:</strong> Cân bằng ngũ hành cho Nhật Chủ hành ${dmElem}. Tăng cường các yếu tố tương sinh tương trợ, khai thông dòng chảy năng lượng tích cực.
          </p>
          <p>
            • <strong>Màu sắc & Phương vị hành mệnh:</strong> Ưu tiên gam màu tương hợp với bản mệnh, chọn không gian sống và bàn làm việc thoáng đãng, hướng về phương vị đón ánh sáng tự nhiên.
          </p>
          <p>
            • <strong>Ngành nghề tương hợp:</strong> Công nghệ thông tin, trí tuệ nhân tạo, truyền thông, thiết kế sáng tạo, ngoại giao, nghiên cứu chiến lược và tài chính.
          </p>
        </div>
      </article>
    `;
  }
}

// ==========================================================================
// TAB 5: VẬN HẠN 12 THÁNG & LƯU NGUYỆT MỆNH CUNG
// ==========================================================================
function renderDedicatedMonthlyTab(selectedMonth = 1) {
  currentDedicatedMonth = selectedMonth;
  const p = tuviData.personal_info;
  const chambers = tuviData.chambers;
  if (!chambers || chambers.length === 0) return;

  // Header Subtitle
  const subEl = document.getElementById("thangam-header-subtitle");
  if (subEl) {
    subEl.innerText = `Lưu Niên Năm ${p.analysis_year_solar} (${p.analysis_year_lunar}) • Đương Số: ${p.name} (${p.age} Tuổi)`;
  }

  // 1. Build 12-Month Selector Buttons
  const selectorEl = document.getElementById("thangam-month-selector");
  if (selectorEl) {
    let selectorHtml = "";
    for (let m = 1; m <= 12; m++) {
      const c_m = chambers.find(c => c.nguyet_han === m) || chambers[(m - 1) % 12];
      const isActive = (m === selectedMonth) ? "active" : "";
      selectorHtml += `
        <div class="month-pill ${isActive}" onclick="renderDedicatedMonthlyTab(${m})">
          <div class="pill-month-num">Tháng ${m} ÂL</div>
          <div class="pill-chamber-tag">[${c_m.name} - ${c_m.chi}]</div>
        </div>
      `;
    }
    selectorEl.innerHTML = selectorHtml;
  }

  // 2. Find Month Chamber and Aspects
  const monthChamber = chambers.find(c => c.nguyet_han === selectedMonth) || chambers[(selectedMonth - 1) % 12];
  const conn = connectionMap[monthChamber.id] || { tam_hop: [], xung_chieu: '', nhi_hop: '' };
  const xcChamber = chambers.find(c => c.id === conn.xung_chieu) || chambers[0];
  const thChambers = conn.tam_hop.map(tId => chambers.find(c => c.id === tId) || chambers[0]);
  const nhChamber = chambers.find(c => c.id === conn.nhi_hop) || chambers[0];

  // Helper function to extract structured stars from any chamber
  const getChamberStarBundle = (c) => {
    if (!c) return { chinh: [], cat: [], hung: [], luu: [], luuNames: [], allStr: "" };
    const chinh = (c.chinh_tinh || []).map(s => `${s.name}${s.status ? ' (' + s.status + ')' : ''}`);
    const cat = (c.cat_tinh || []).filter(s => !s.is_luu && !s.name.startsWith("L.")).map(s => s.name);
    const hung = (c.hung_tinh || []).filter(s => !s.is_luu && !s.name.startsWith("L.")).map(s => `${s.name}${s.status ? ' (' + s.status + ')' : ''}`);
    
    const luuNames = [];
    [...(c.luu_tinh || []), ...(c.cat_tinh || []), ...(c.hung_tinh || [])].forEach(s => {
      if (s.is_luu || s.name.startsWith("L.")) {
        const nm = s.name.startsWith("L.") ? s.name : `L.${s.name}`;
        if (!luuNames.includes(nm)) luuNames.push(nm);
      }
    });
    return {
      chinh,
      cat,
      hung,
      luuNames,
      chinhStr: chinh.join(", ") || "Vô Chính Diệu",
      catStr: cat.join(", ") || "Không có",
      hungStr: hung.join(", ") || "Không có",
      luuStr: luuNames.join(", ") || "Không có"
    };
  };

  // Helper for flying star meanings
  const getFlyingStarDetail = (sName) => {
    const dict = {
      "L.Thái Tuế": "Lưu Thái Tuế kích hoạt vận trình mới, mang lại cơ hội khẳng định uy tín, đảm đương vị trí nòng cốt, giải quyết thủ tục giấy tờ. Cần khiêm nhường đối đãi để phòng thị phi tranh chấp danh dự.",
      "L.Lộc Tồn": "Lưu Lộc Tồn mang lại dòng tiền thực tế, cơ hội tích lũy tài sản thặng dư, lộc trời ban hoặc thưởng lớn từ kinh doanh. Rất cát lợi cho việc đầu tư an toàn và giữ tiền.",
      "L.Kình Dương": "Lưu Kình Dương mang tính xung sát, trực diện, dễ gặp cạnh tranh gay gắt nơi làm việc hoặc va chạm quan điểm. Cần giữ bình tĩnh, cẩn trọng khi lái xe và tránh vật sắc nhọn dao kéo.",
      "L.Đà La": "Lưu Đà La chủ về sự quanh co, trì hoãn, ngấm ngầm cản trở hoặc trăn trở suy tư nội tâm. Lời khuyên: Tuyệt đối không nóng vội đốt cháy giai đoạn, cần kiên nhẫn tháo gỡ từng nút thắt tỉ mỉ.",
      "L.Tang Môn": "Lưu Tang Môn chủ về nỗi lo toan gia đạo, chăm sóc con nhỏ hoặc người thân lớn tuổi, hao tổn tâm sức vì gia đình. Cần điều dưỡng tinh thần, giữ suy nghĩ tích cực lạc quan.",
      "L.Bạch Hổ": "Lưu Bạch Hổ đòi hỏi bản lĩnh kiên cường, gánh vác áp lực lớn hoặc đối diện các vấn đề pháp lý hồ sơ. Sự kiên trì và chính trực sẽ giúp đương số vượt qua mọi thử thách.",
      "L.Thiên Mã": "Lưu Thiên Mã tạo động lực dịch chuyển, công tác, ngoại giao xa xôi, thay đổi không gian làm việc. Càng năng động đi lại thì cơ hội hanh thông tài lộc càng mở rộng.",
      "L.Hóa Lộc": "Lưu Hóa Lộc là đệ nhất cát tinh tài vận, khai thông dòng tiền dồi dào, kinh doanh đắc lợi, các mối quan hệ xã giao đem lại lợi ích thiết thực.",
      "L.Hóa Quyền": "Lưu Hóa Quyền gia tăng uy lực, quyền tự quyết và bản lĩnh chỉ huy. Đương số nắm quyền quyết định then chốt, được mọi người nể phục và tin tưởng giao phó trọng trách.",
      "L.Hóa Khoa": "Lưu Hóa Khoa chủ về trí tuệ sáng suốt, học vấn bằng cấp, thanh danh lan tỏa và đệ nhất cát tinh giải cứu tai ách, gặp hung hóa cát thuận lợi.",
      "L.Hóa Kỵ": "Lưu Hóa Kỵ gây nghi kỵ, hiểu lầm, thị phi gièm pha hoặc trục trặc trong giao tiếp. Cần minh bạch tiền bạc, rà soát hợp đồng cẩn mật và dĩ hòa vi quý.",
      "L.Đào Hoa": "Lưu Đào Hoa chủ về cát duyên nhân ái, sức hút cá nhân nổi bật, giao tiếp mở rộng, mang lại nhiều cơ hội hợp tác vui vẻ.",
      "L.Hồng Loan": "Lưu Hồng Loan mang lại duyên may cát tường, không khí gia đình hòa hợp, đón nhận sự yêu thương và giúp đỡ từ mọi người xung quanh.",
      "L.Thiên Hỷ": "Lưu Thiên Hỷ chủ về tin vui hân hoan từ xa báo về, tiệc tùng gặp gỡ người thân bạn bè, hỷ sự tốt lành.",
      "L.Thiên Khôi": "Lưu Thiên Khôi báo hiệu có quý nhân bề trên, bậc trưởng bối nâng đỡ, đề bạt chỉ dẫn trong sự nghiệp học vấn.",
      "L.Thiên Việt": "Lưu Thiên Việt là quý nhân âm thầm trợ lực phía sau, mở ra giải pháp tháo gỡ bế tắc bất ngờ.",
      "L.Thiên Khốc": "Lưu Thiên Khốc dễ gây tâm lý mệt mỏi, suy nghĩ trầm tư hoặc xúc động; nên chia sẻ cùng người thân để giải tỏa áp lực nội tâm.",
      "L.Thiên Hư": "Lưu Thiên Hư nhắc nhở đề phòng hao hụt nhỏ hoặc những lời hứa hẹn thiếu thực tế từ người ngoài."
    };
    return dict[sName] || `Sao lưu ${sName} kích hoạt nguồn năng lượng biến động đặc thù tại cung vị, đòi hỏi đương số ứng biến linh hoạt.`;
  };

  // Calculate Scores
  const scores = calculateHanScores(monthChamber, xcChamber, thChambers);

  const mBundle = getChamberStarBundle(monthChamber);
  const xcBundle = getChamberStarBundle(xcChamber);
  const th1Bundle = getChamberStarBundle(thChambers[0]);
  const th2Bundle = getChamberStarBundle(thChambers[1]);
  const nhBundle = getChamberStarBundle(nhChamber);

  // Tuần Triệt impact
  let ttHtml = "";
  if (monthChamber.tuan_triet && monthChamber.tuan_triet.includes("Triệt")) {
    ttHtml = `<div style="background: #fff1f2; border-left: 4px solid #dc2626; padding: 8px 12px; border-radius: 4px; margin-top: 10px; font-size: 0.84rem; color: #991b1b;">
      <strong>🛡️ Tác động Triệt Không tại Mệnh Tháng:</strong> Chém đứt các hung sát tinh quấy nhiễu nhưng đồng thời làm giảm 50% độ sáng cát tinh. Lời khuyên: Tránh đầu cơ mạo hiểm, kiên nhẫn tích lũy, mọi quyết định lớn cần suy xét cẩn trọng.
    </div>`;
  } else if (monthChamber.tuan_triet && monthChamber.tuan_triet.includes("Tuần")) {
    ttHtml = `<div style="background: #eff6ff; border-left: 4px solid #2563eb; padding: 8px 12px; border-radius: 4px; margin-top: 10px; font-size: 0.84rem; color: #1e40af;">
      <strong>🛡️ Tác động Tuần Không tại Mệnh Tháng:</strong> Đóng vai trò chiếc khiên bảo bọc bình an suốt 30 ngày Âm lịch, hóa giải hiểm họa tai ương, làm chậm nhịp độ để đảm bảo sự chắc chắn bền vững.
    </div>`;
  }

  // Detect Combinations across Month, Opposite, Trines, Hexagonal
  const allAspectLuu = [
    ...mBundle.luuNames,
    ...xcBundle.luuNames,
    ...th1Bundle.luuNames,
    ...th2Bundle.luuNames,
    ...nhBundle.luuNames
  ];
  
  // Special combination callouts
  let comboCalloutHtml = "";
  const hasLuuLoc = allAspectLuu.includes("L.Hóa Lộc");
  const hasLuuQuyen = allAspectLuu.includes("L.Hóa Quyền");
  const hasLuuKhoa = allAspectLuu.includes("L.Hóa Khoa");
  const hasLuuLocTon = allAspectLuu.includes("L.Lộc Tồn");
  const hasLuuTang = allAspectLuu.includes("L.Tang Môn");
  const hasLuuHo = allAspectLuu.includes("L.Bạch Hổ");
  const hasLuuKinh = allAspectLuu.includes("L.Kình Dương");
  const hasLuuDa = allAspectLuu.includes("L.Đà La");

  if (hasLuuLoc && hasLuuQuyen) {
    comboCalloutHtml += `
      <div class="aspect-combo-callout">
        <strong>🌟 CÁCH CỤC ĐẶC BIỆT: LỘC QUYỀN HỘI HỢP (Tam Hóa Tương Hùng):</strong> 
        Trong tháng ${selectedMonth} ÂL, luồng khí của <strong>Lưu Hóa Quyền</strong> (tại ${mBundle.luuNames.includes("L.Hóa Quyền") ? "Bản Cung" : "Cung Chiếu"}) hội ngộ cùng <strong>Lưu Hóa Lộc</strong> (tại ${th2Bundle.luuNames.includes("L.Hóa Lộc") ? "Cung " + thChambers[1].name : "Cung Chiếu"})! 
        Đây là tổ hợp thượng cách: Quyền tinh mang lại tiếng nói quyết định, bản lĩnh điều hành; Lộc tinh mang lại dòng tiền hanh thông, đối tác chi trả sòng phẳng. Đương số vừa khẳng định vị thế công danh, vừa gặt hái tài chính thực chất!
      </div>
    `;
  } else if (hasLuuLoc && hasLuuLocTon) {
    comboCalloutHtml += `
      <div class="aspect-combo-callout">
        <strong>💰 CÁCH CỤC ĐẶC BIỆT: SONG LỘC TRIỀU VIÊN:</strong>
        Lưu Hóa Lộc và Lưu Lộc Tồn cùng hội tụ chiếu về Mệnh tháng, mở ra vận may tiền tài đột phá, nhiều nguồn thu nhập cùng lúc sinh lời.
      </div>
    `;
  }

  if (hasLuuTang && hasLuuHo) {
    comboCalloutHtml += `
      <div class="aspect-combo-callout" style="border-left-color: #dc2626; background: #fff5f5; color: #991b1b;">
        <strong>⚠️ THẾ TANG HỔ TƯƠNG PHÙNG:</strong>
        Lưu Tang Môn và Lưu Bạch Hổ cùng hợp chiếu, nhắc nhở đương số trong tháng này cần chú ý cân bằng sức khỏe, quan tâm nhiều hơn đến con nhỏ hoặc người thân lớn tuổi, tránh làm việc quá sức gây căng thẳng thần kinh.
      </div>
    `;
  }

  if (hasLuuKinh && hasLuuDa) {
    comboCalloutHtml += `
      <div class="aspect-combo-callout" style="border-left-color: #ea580c; background: #fff7ed; color: #9a3412;">
        <strong>🛡️ THẾ KÌNH ĐÀ HIỆP CHIẾU:</strong>
        Kình Dương chủ va chạm trực diện, Đà La chủ cản trở ngấm ngầm cùng giao hội. Lời khuyên: Giữ tâm bình thản, kiên nhẫn xử lý giấy tờ pháp lý, tránh đôi co tranh luận nơi công cộng.
      </div>
    `;
  }

  // Detail HTML Construction
  const detailContainer = document.getElementById("thangam-detail-container");
  if (detailContainer) {
    let detailHtml = `
      <!-- Banner Cung Mệnh Tháng -->
      <div class="month-menh-banner">
        <div class="month-menh-header">
          <div>
            <div style="font-size: 0.85rem; color: #b45309; font-weight: bold; text-transform: uppercase;">Lưu Nguyệt Mệnh Cung • Tháng ${selectedMonth} Âm Lịch</div>
            <div class="month-menh-title">CUNG ${monthChamber.name.toUpperCase()} TẠI ${monthChamber.can} ${monthChamber.chi.toUpperCase()} (HÀNH ${monthChamber.element.toUpperCase()})</div>
          </div>
          <div style="text-align: right;">
            <span style="background: #78350f; color: #fef3c7; padding: 4px 10px; border-radius: 20px; font-size: 0.8rem; font-weight: bold;">
              Đại hạn: ${monthChamber.dai_han} - ${monthChamber.dai_han + 9} tuổi
            </span>
            ${monthChamber.is_than ? '<span style="background: #dc2626; color: #ffffff; padding: 4px 10px; border-radius: 20px; font-size: 0.8rem; font-weight: bold; margin-left: 6px;">THÂN CƯ TẠI ĐÂY</span>' : ''}
          </div>
        </div>

        <div class="month-stars-grid">
          <div class="month-star-cell">
            <div style="color: #64748b; font-size: 0.75rem; font-weight: bold; text-transform: uppercase;">Chính Tinh Tọa Thủ</div>
            <div style="font-size: 1rem; font-weight: bold; color: #8b0000; margin-top: 3px;">${mBundle.chinhStr}</div>
          </div>
          <div class="month-star-cell">
            <div style="color: #64748b; font-size: 0.75rem; font-weight: bold; text-transform: uppercase;">Tuần / Triệt Án Ngữ</div>
            <div style="font-size: 1rem; font-weight: bold; color: #dc2626; margin-top: 3px;">${monthChamber.tuan_triet || "Không bị án ngữ"}</div>
          </div>
          <div class="month-star-cell">
            <div style="color: #64748b; font-size: 0.75rem; font-weight: bold; text-transform: uppercase;">Cát Tinh Hội Tụ</div>
            <div style="font-size: 0.88rem; color: var(--color-moc); font-weight: 600; margin-top: 3px;">${mBundle.catStr}</div>
          </div>
          <div class="month-star-cell">
            <div style="color: #64748b; font-size: 0.75rem; font-weight: bold; text-transform: uppercase;">Hung Sát Tinh</div>
            <div style="font-size: 0.88rem; color: var(--color-hoa); font-weight: 600; margin-top: 3px;">${mBundle.hungStr}</div>
          </div>
        </div>

        <div style="margin-top: 12px; padding: 10px 14px; background: rgba(109, 40, 217, 0.05); border: 1px solid rgba(109, 40, 217, 0.2); border-radius: 6px;">
          <div style="color: #6d28d9; font-size: 0.8rem; font-weight: bold; text-transform: uppercase;">⚡ Sao Lưu Năm ${p.analysis_year_solar} Kích Hoạt Tại Mệnh Tháng:</div>
          <div style="font-size: 0.92rem; font-weight: bold; color: #5b21b6; margin-top: 2px;">${mBundle.luuStr}</div>
        </div>
        ${ttHtml}
      </div>

      <!-- ==========================================================================
           KHỐI PHÂN TÍCH TƯƠNG TÁC TINH ĐẨU & HỘI CHIẾU SAO LƯU CHI TIẾT
           (TỌA THỦ - XUNG CHIẾU - TAM HỢP - NHỊ HỢP)
           ========================================================================== -->
      <div style="margin-top: 10px; margin-bottom: 24px;">
        <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px; border-bottom: 2px solid var(--color-gold); padding-bottom: 6px;">
          <h3 style="font-size: 1.15rem; color: #78350f; font-family: var(--font-serif); margin: 0;">
            🌌 HỘI CHIẾU TINH ĐẨU & PHÂN TÍCH SAO LƯU CHI TIẾT (TỌA THỦ - XUNG CHIẾU - TAM HỢP - NHỊ HỢP)
          </h3>
          <span style="font-size: 0.8rem; background: #fef3c7; color: #92400e; padding: 3px 8px; border-radius: 12px; font-weight: bold;">
            Đa Chiều 4 Hướng
          </span>
        </div>

        ${comboCalloutHtml}

        <div class="aspect-analysis-grid">
          
          <!-- Card 1: TỌA THỦ BẢN CUNG -->
          <div class="aspect-box aspect-box-toathu">
            <div class="aspect-box-header">
              <div class="aspect-box-title">
                <span>🎯 1. Tọa Thủ Bản Cung (Mệnh Tháng)</span>
              </div>
              <span class="aspect-chamber-badge" style="background: #f3e8ff; color: #6b21a8;">
                ${monthChamber.name} (${monthChamber.can} ${monthChamber.chi})
              </span>
            </div>

            <div class="aspect-stars-strip">
              <span style="font-size: 0.74rem; font-weight: bold; color: #64748b; margin-right: 4px;">Tinh đẩu:</span>
              ${mBundle.chinh.map(s => `<span class="aspect-pill aspect-pill-chinh">${s}</span>`).join(" ")}
              ${mBundle.luuNames.map(s => `<span class="aspect-pill aspect-pill-luu">${s}</span>`).join(" ")}
              ${mBundle.cat.slice(0, 4).map(s => `<span class="aspect-pill aspect-pill-cat">${s}</span>`).join(" ")}
            </div>

            <div class="aspect-body-text">
              <p>
                <strong>Ảnh hưởng gì đến bản cung?</strong> 
                Bản cung Mệnh tháng đóng tại <strong>${monthChamber.name} (${monthChamber.chi})</strong> là hạt nhân điều phối vận trình suốt 30 ngày. 
                ${mBundle.chinh.length > 0 ? `Chính tinh <strong>${mBundle.chinhStr}</strong> làm chủ thần thức, định hình tư duy và hành động chính của đương số.` : `Cung Vô Chính Diệu, cần mượn lực dội từ Cung Xung Chiếu để định hình phương hướng.`}
              </p>
              
              ${mBundle.luuNames.length > 0 ? `
                <div style="background: rgba(124, 58, 237, 0.06); padding: 8px 12px; border-radius: 6px; margin: 8px 0;">
                  <strong style="color: #6d28d9; font-size: 0.82rem;">⚡ Chi tiết các Sao Lưu tọa thủ trực tiếp:</strong>
                  <ul style="margin: 4px 0 0 16px; padding: 0; font-size: 0.82rem; line-height: 1.55;">
                    ${mBundle.luuNames.map(s => `<li><strong>${s}:</strong> ${getFlyingStarDetail(s)}</li>`).join("")}
                  </ul>
                </div>
              ` : `<p style="font-style: italic; color: #64748b;">Bản cung không có sao lưu đóng trực tiếp, giữ nhịp độ vận trình ổn định theo tính chất các chính tinh cố định.</p>`}

              <p style="margin-top: 6px;">
                <strong>Chiếu đi đâu?</strong> 
                Bản cung mang năng lượng của <em>${mBundle.chinhStr}</em> cùng các sao lưu <em>${mBundle.luuStr}</em> chiếu thẳng sang Cung <strong>${xcChamber.name} (${xcChamber.chi})</strong>, đồng thời phóng luồng năng lượng tam hợp sang Cung <strong>${thChambers[0].name}</strong> và <strong>${thChambers[1].name}</strong>, làm thay đổi thái độ và cách thức đương số đối nhân xử thế.
              </p>
            </div>
          </div>

          <!-- Card 2: XUNG CHIẾU -->
          <div class="aspect-box aspect-box-xungchieu">
            <div class="aspect-box-header">
              <div class="aspect-box-title">
                <span>⚡ 2. Cung Xung Chiếu (Chính Diện Dội Sang)</span>
              </div>
              <span class="aspect-chamber-badge" style="background: #fee2e2; color: #991b1b;">
                ${xcChamber.name} (${xcChamber.can} ${xcChamber.chi})
              </span>
            </div>

            <div class="aspect-stars-strip">
              <span style="font-size: 0.74rem; font-weight: bold; color: #64748b; margin-right: 4px;">Tinh đẩu chiếu:</span>
              ${xcBundle.chinh.map(s => `<span class="aspect-pill aspect-pill-chinh">${s}</span>`).join(" ")}
              ${xcBundle.luuNames.map(s => `<span class="aspect-pill aspect-pill-luu">${s}</span>`).join(" ")}
              ${xcBundle.hung.slice(0, 3).map(s => `<span class="aspect-pill aspect-pill-hung">${s}</span>`).join(" ")}
              ${xcBundle.cat.slice(0, 3).map(s => `<span class="aspect-pill aspect-pill-cat">${s}</span>`).join(" ")}
            </div>

            <div class="aspect-body-text">
              <p>
                <strong>Cái gì chiếu sang?</strong> 
                Cung đối xứng 180 độ là Cung <strong>${xcChamber.name} (${xcChamber.can} ${xcChamber.chi})</strong> dội thẳng luồng năng lượng của: 
                <strong>${xcBundle.chinhStr}</strong>, cát hung tinh và đặc biệt là <strong>${xcBundle.luuStr}</strong> vào Mệnh tháng!
              </p>
              
              <p>
                <strong>Bản chất tác động ngoại cảnh:</strong> 
                Xung chiếu đại diện cho môi trường bên ngoài, đối tác, khách hàng hoặc những biến động khách quan từ xã hội dội vào đương số khi bước chân ra ngoài:
                ${xcBundle.hung.length > 0 || xcBundle.luuNames.some(s => s.includes("Kình") || s.includes("Kỵ") || s.includes("Tang")) ? 
                  `Cung đối diện có sát tinh hoặc sao lưu mang tính xung động, báo hiệu ngoại cảnh có sức ép cạnh tranh gay gắt hoặc đòi hỏi khắt khe từ đối tác. Đương số cần chuẩn bị kế hoạch kỹ lưỡng, dĩ hòa vi quý.` :
                  `Cung đối diện thuần hòa hoặc nhiều cát tinh, báo hiệu ra ngoài gặp thuận lợi, đối tác hợp tác vui vẻ, có quý nhân tương trợ mở lối.`}
              </p>

              ${xcBundle.luuNames.length > 0 ? `
                <div style="background: rgba(220, 38, 38, 0.05); padding: 6px 10px; border-radius: 6px; margin: 6px 0; font-size: 0.82rem;">
                  <strong style="color: #b91c1c;">⚡ Sao lưu từ Cung ${xcChamber.name} dội sang:</strong>
                  <ul style="margin: 2px 0 0 16px; padding: 0;">
                    ${xcBundle.luuNames.map(s => `<li><strong>${s}:</strong> ${getFlyingStarDetail(s)}</li>`).join("")}
                  </ul>
                </div>
              ` : ''}

              <p style="margin-top: 4px;">
                <strong>Lời khuyên ứng biến:</strong> Lấy thế điềm tĩnh của bản cung làm trọng, chủ động nắm bắt cơ hội từ bên ngoài dội vào nhưng không để các thị phi ngoại cảnh làm dao động tâm trí.
              </p>
            </div>
          </div>

          <!-- Card 3: TAM HỢP CHIẾU VỀ -->
          <div class="aspect-box aspect-box-tamhop">
            <div class="aspect-box-header">
              <div class="aspect-box-title">
                <span>🔺 3. Cặp Cung Tam Hợp (Thế Chân Vạc Hội Tụ)</span>
              </div>
              <span class="aspect-chamber-badge" style="background: #fef3c7; color: #92400e;">
                ${monthChamber.chi} - ${thChambers[0].chi} - ${thChambers[1].chi}
              </span>
            </div>

            <div class="aspect-stars-strip">
              <span style="font-size: 0.74rem; font-weight: bold; color: #64748b; margin-right: 4px;">Tinh đẩu hợp chiếu:</span>
              <span class="aspect-pill aspect-pill-cat">${thChambers[0].name}: ${th1Bundle.chinhStr}</span>
              ${th1Bundle.luuNames.map(s => `<span class="aspect-pill aspect-pill-luu">${s}</span>`).join(" ")}
              <span class="aspect-pill aspect-pill-cat">${thChambers[1].name}: ${th2Bundle.chinhStr}</span>
              ${th2Bundle.luuNames.map(s => `<span class="aspect-pill aspect-pill-luu">${s}</span>`).join(" ")}
            </div>

            <div class="aspect-body-text">
              <p>
                <strong>Tam hợp cái gì chiếu vào thì như thế nào?</strong> 
                Hai cung trụ cột trong tam hợp là Cung <strong>${thChambers[0].name} (${thChambers[0].chi})</strong> và Cung <strong>${thChambers[1].name} (${thChambers[1].chi})</strong> cùng hợp lực chiếu về Mệnh tháng, tạo thành thế kiềng ba chân vững chãi.
              </p>

              <div style="background: rgba(217, 119, 6, 0.06); padding: 8px 12px; border-radius: 6px; margin: 8px 0; font-size: 0.82rem;">
                <p style="margin: 0 0 4px 0;">
                  • <strong>Từ Cung ${thChambers[0].name} (${thChambers[0].chi}):</strong> Phóng năng lượng của <em>${th1Bundle.chinhStr}</em>, cát tinh <em>${th1Bundle.catStr}</em> ${th1Bundle.luuNames.length > 0 ? `và sao lưu <strong>[${th1Bundle.luuStr}]</strong>` : ''}.
                </p>
                <p style="margin: 0;">
                  • <strong>Từ Cung ${thChambers[1].name} (${thChambers[1].chi}):</strong> Phóng năng lượng của <em>${th2Bundle.chinhStr}</em>, cát tinh <em>${th2Bundle.catStr}</em> ${th2Bundle.luuNames.length > 0 ? `và sao lưu <strong>[${th2Bundle.luuStr}]</strong>` : ''}.
                </p>
              </div>

              <p>
                <strong>Ý nghĩa chiến lược:</strong> 
                Tam hợp đại diện cho nguồn lực nội tại, hậu phương gia đình và bạn bè cộng sự. Sức mạnh tổng hòa của tam hợp trong tháng ${selectedMonth} giúp đương số có điểm tựa vững vàng để triển khai các mục tiêu sự nghiệp và tài chính, tiến có thể công, thoái có nơi chở che.
              </p>
            </div>
          </div>

          <!-- Card 4: NHỊ HỢP -->
          <div class="aspect-box aspect-box-nhihop">
            <div class="aspect-box-header">
              <div class="aspect-box-title">
                <span>🌿 4. Cung Nhị Hợp (Trợ Lực Ngầm & Lục Hợp)</span>
              </div>
              <span class="aspect-chamber-badge" style="background: #dbeafe; color: #1e40af;">
                ${monthChamber.chi} hợp ${nhChamber.chi}
              </span>
            </div>

            <div class="aspect-stars-strip">
              <span style="font-size: 0.74rem; font-weight: bold; color: #64748b; margin-right: 4px;">Cung hợp:</span>
              <span class="aspect-pill" style="background: #eff6ff; color: #1e40af; border: 1px solid #bfdbfe;">
                ${nhChamber.name} (${nhChamber.can} ${nhChamber.chi})
              </span>
              ${nhBundle.chinh.map(s => `<span class="aspect-pill aspect-pill-chinh">${s}</span>`).join(" ")}
              ${nhBundle.luuNames.map(s => `<span class="aspect-pill aspect-pill-luu">${s}</span>`).join(" ")}
            </div>

            <div class="aspect-body-text">
              <p>
                <strong>Nhị hợp cái gì chiếu vào thì như thế nào?</strong> 
                Cung Nhị Hợp của tháng là Cung <strong>${nhChamber.name} (${nhChamber.can} ${nhChamber.chi} - Hành ${nhChamber.element})</strong>. 
                Quan hệ Lục Hợp mang tính thẩm thấu ngầm, không lộ ra mặt nổi nhưng chi phối sâu sắc tâm lý và sức khỏe nội tại.
              </p>

              <div style="background: rgba(37, 99, 235, 0.05); padding: 8px 12px; border-radius: 6px; margin: 8px 0; font-size: 0.82rem;">
                <p style="margin: 0 0 4px 0;">
                  • <strong>Tương tác Ngũ Hành:</strong> Bản cung (${monthChamber.element}) và Cung nhị hợp (${nhChamber.element}): 
                  ${monthChamber.element === nhChamber.element ? 'Tỷ hòa hỗ trợ, năng lượng đồng điệu êm ả.' : 
                    (monthChamber.element === 'Thổ' && nhChamber.element === 'Kim') ? 'Thổ sinh Kim (Sinh xuất) — Đương số cần dành thời gian, tâm lực chăm chút cho phương diện này, tránh để hao tổn thể lực.' :
                    (monthChamber.element === 'Thủy' && nhChamber.element === 'Mộc') ? 'Thủy sinh Mộc (Sinh xuất) — Nuôi dưỡng ngầm, tích phúc báu.' :
                    (nhChamber.element === 'Thổ' && monthChamber.element === 'Kim') ? 'Thổ sinh Kim (Sinh nhập) — Hưởng lợi ngầm, có quý nhân bí mật tiếp sức.' :
                    `Quan hệ sinh khắc âm dương điều tiết nhịp sống.`}
                </p>
                <p style="margin: 0;">
                  • <strong>Tinh đẩu ngấm ngầm:</strong> ${nhBundle.chinhStr} ${nhBundle.luuNames.length > 0 ? `cùng sao lưu [${nhBundle.luuStr}]` : ''}.
                </p>
              </div>

              <p>
                <strong>Tác động thực tế:</strong> 
                Cho biết những việc kín đáo, hậu trường (sức khỏe nội tạng, nguồn tiền dự phòng, sự trợ giúp thầm lặng của người thân). Đương số cần duy trì lối sống lành mạnh, chăm sóc cẩn thận phần gốc rễ này để có sức bật vững chãi nhất.
              </p>
            </div>
          </div>

        </div>
      </div>

      <!-- 5 Trục Vận Mệnh Cốt Lõi (Được Nâng Cấp Tên Sao Trực Tiếp) -->
      <h3 style="font-size: 1.15rem; color: #78350f; font-family: var(--font-serif); margin-bottom: 12px; border-left: 4px solid var(--color-gold); padding-left: 8px;">
        PHÂN TÍCH 5 TRỤC VẬN MỆNH TRỌNG TÂM TRONG THÁNG ${selectedMonth} ÂM LỊCH
      </h3>
      <div class="five-axes-container">
        
        <!-- Axis 1: Bản Thân -->
        <div class="axis-card">
          <div class="axis-card-header">
            <div class="axis-card-title">🧘 1. Bản Thân & Tâm Trí (Mệnh Tháng)</div>
            <div class="axis-score-badge">${getStarRatingHtml(scores.health)}</div>
          </div>
          <div class="axis-card-body">
            Khí sắc và tinh thần của đương số trong tháng ${selectedMonth} chịu sự chi phối mạnh của <strong>${mBundle.chinhStr}</strong> tọa thủ tại <strong>${monthChamber.name}</strong> 
            ${mBundle.luuNames.length > 0 ? `cùng các sao lưu <strong>[${mBundle.luuStr}]</strong>` : ''}. 
            ${scores.health >= 4 ? 
              'Tâm thế tự chủ, bản lĩnh vững vàng, có tầm nhìn chiến lược và khả năng đưa ra những quyết sách quan trọng.' : 
              'Đôi lúc có áp lực hoặc sự trăn trở nội tâm do tác động của sát tinh/sao lưu; nên duy trì tập luyện thể thao, giữ giấc ngủ sâu và tâm an định.'}
          </div>
        </div>

        <!-- Axis 2: Sự Nghiệp -->
        <div class="axis-card">
          <div class="axis-card-header">
            <div class="axis-card-title">💼 2. Công Danh & Sự Nghiệp (Lưu Quan)</div>
            <div class="axis-score-badge">${getStarRatingHtml(scores.career)}</div>
          </div>
          <div class="axis-card-body">
            Trục sự nghiệp được tiếp nhận luồng khí từ Cung <strong>${thChambers[0].name} (${thChambers[0].chi})</strong> hội tụ cùng Mệnh tháng. 
            ${hasLuuQuyen ? 'Có <strong>Lưu Hóa Quyền</strong> kích hoạt: tháng này uy quyền thăng tiến, có tiếng nói dẫn dắt, được đồng nghiệp và đối tác tin tưởng giao phó trọng trách lớn.' : ''}
            ${scores.career >= 4 ? 
              'Công việc hanh thông thuận lợi, có cơ hội bứt phá mở rộng quy mô hoặc triển khai dự án mới thành công.' : 
              'Cần tỉ mỉ trong từng khâu xử lý, kiểm tra kỹ hồ sơ hợp đồng trước khi phê duyệt, tránh nóng vội trong các quyết định điều hành.'}
          </div>
        </div>

        <!-- Axis 3: Tài Chính -->
        <div class="axis-card">
          <div class="axis-card-header">
            <div class="axis-card-title">💰 3. Tài Chính & Dòng Tiền (Lưu Tài)</div>
            <div class="axis-score-badge">${getStarRatingHtml(scores.wealth)}</div>
          </div>
          <div class="axis-card-body">
            Dòng tiền của tháng chịu ảnh hưởng từ Cung tam hợp <strong>${thChambers[1].name}</strong> và Cung xung chiếu <strong>${xcChamber.name}</strong>.
            ${hasLuuLoc ? 'Đắc <strong>Lưu Hóa Lộc</strong> chiếu về: tài khí dồi dào, các khoản doanh thu hoặc hợp đồng ký kết đều mang lại lợi nhuận thực tế rõ rệt.' : ''}
            ${scores.wealth >= 4 ? 
              'Dòng tiền lưu thông tích cực, có thêm các cơ hội gia tăng thu nhập từ chuyên môn và đầu tư an toàn.' : 
              'Cần kiểm soát chi tiêu hợp lý, tránh cho vay mượn thiếu cam kết hoặc đầu tư vào các kênh mạo hiểm có độ rủi ro cao.'}
          </div>
        </div>

        <!-- Axis 4: Gia Đạo & Tình Duyên -->
        <div class="axis-card">
          <div class="axis-card-header">
            <div class="axis-card-title">🏡 4. Gia Đạo & Tình Cảm (Lưu Phối/Tử)</div>
            <div class="axis-score-badge">${getStarRatingHtml(scores.relationships)}</div>
          </div>
          <div class="axis-card-body">
            Gia đạo và tình cảm với người phối ngẫu, con cái trong tháng ${selectedMonth}. 
            ${hasLuuTang ? 'Có <strong>Lưu Tang Môn</strong> xuất hiện: cần dành nhiều thời gian chăm sóc con cái và thăm hỏi sức khỏe người thân lớn tuổi.' : ''}
            ${scores.relationships >= 4 ? 
              'Gia đạo êm ấm, vợ chồng đồng lòng thấu hiểu, con cái ngoan ngoãn mang lại nguồn động lực tinh thần to lớn.' : 
              'Cần lắng nghe và bao dung trước những quan điểm khác biệt trong gia đình, dĩ hòa vi quý để giữ trọn vẹn sự bình an của tổ ấm.'}
          </div>
        </div>

        <!-- Axis 5: Sức Khỏe & Đi Lại -->
        <div class="axis-card">
          <div class="axis-card-header">
            <div class="axis-card-title">🚗 5. Sức Khỏe & Xuất Hành (Lưu Di/Tật)</div>
            <div class="axis-score-badge">${getStarRatingHtml(scores.overall)}</div>
          </div>
          <div class="axis-card-body">
            Trục xuất hành ngoại giao chịu sự chi phối từ Cung <strong>${xcChamber.name} (${xcChamber.chi})</strong> và Cung nhị hợp <strong>${nhChamber.name} (${nhChamber.chi})</strong>.
            ${allAspectLuu.includes("L.Thiên Mã") ? 'Có <strong>Lưu Thiên Mã</strong> kích hoạt: đi lại công tác xa nhiều, càng di chuyển giao thiệp thì càng mở ra nhiều cơ may.' : ''}
            ${scores.overall >= 4 ? 
              'Xuất hành bình an, đường sá hanh thông, gặp quý nhân trợ lực khi ra ngoài ngoại giao.' : 
              'Chú ý lái xe cẩn thận khi thời tiết xấu hoặc đêm muộn, bảo dưỡng đường tiêu hóa và giấc ngủ, tránh làm việc quá khuya.'}
          </div>
        </div>

      </div>

      <!-- Bộ Tra Cứu Lưu Nhật trong Tháng -->
      <div class="daily-transit-box">
        <div style="display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px; border-bottom: 1px solid #e2e8f0; padding-bottom: 8px; margin-bottom: 12px;">
          <div>
            <strong style="color: #78350f; font-size: 0.95rem;">📅 TRA CỨU NHẬT HẠN TRONG THÁNG ${selectedMonth} ÂM LỊCH (MÙNG 1 - 30)</strong>
            <div style="font-size: 0.75rem; color: #64748b;">Khởi Mùng 1 tại cung Nguyệt Hạn (${monthChamber.name} tại ${monthChamber.chi}), đếm thuận mỗi ngày 1 cung.</div>
          </div>
          <div style="display: flex; align-items: center; gap: 8px;">
            <label style="font-size: 0.85rem; font-weight: bold; color: #475569;">Chọn ngày ÂL:</label>
            <select id="sel-dedicated-han-day" class="inp-field" style="width: 130px; padding: 4px 8px;" onchange="updateDedicatedDailyView()">
    `;
    
    for (let d = 1; d <= 30; d++) {
      detailHtml += `<option value="${d}">Mùng ${d} ÂL</option>`;
    }
    
    detailHtml += `
            </select>
          </div>
        </div>
        <div id="dedicated-daily-display-box" style="font-size: 0.86rem; line-height: 1.6; color: #1e293b; background: #fafafa; padding: 12px 16px; border-radius: 6px; border-left: 3px solid var(--color-gold);">
          <!-- Rendered dynamically by updateDedicatedDailyView -->
        </div>
      </div>
    `;
    detailContainer.innerHTML = detailHtml;
    
    // Call daily view update
    updateDedicatedDailyView();
  }

  // 3. Build Comparative Matrix Table
  const matrixTable = document.getElementById("thangam-matrix-table");
  if (matrixTable) {
    let tableHtml = `
      <thead>
        <tr>
          <th style="width: 7%;">Tháng ÂL</th>
          <th style="width: 17%;">Mệnh Tháng & Sao Lưu Tọa Thủ</th>
          <th style="width: 18%;">Xung Chiếu (Chiếu Đối Diện)</th>
          <th style="width: 22%;">Tam Hợp (Thế Chân Vạc Hội Về)</th>
          <th style="width: 16%;">Nhị Hợp (Trợ Lực Ngầm)</th>
          <th style="width: 10%;">Tài Lộc/Sự Nghiệp</th>
          <th style="width: 10%;">Đánh Giá</th>
        </tr>
      </thead>
      <tbody>
    `;

    for (let m = 1; m <= 12; m++) {
      const c_m = chambers.find(c => c.nguyet_han === m) || chambers[(m - 1) % 12];
      const c_conn = connectionMap[c_m.id] || { tam_hop: [], xung_chieu: '', nhi_hop: '' };
      const c_xc = chambers.find(c => c.id === c_conn.xung_chieu) || chambers[0];
      const c_th = c_conn.tam_hop.map(tId => chambers.find(c => c.id === tId) || chambers[0]);
      const c_nh = chambers.find(c => c.id === c_conn.nhi_hop) || chambers[0];
      const m_scores = calculateHanScores(c_m, c_xc, c_th);

      const m_chinh = c_m.chinh_tinh.map(s => s.name).join(", ") || "Vô Chính Diệu";
      const m_tt = c_m.tuan_triet ? `<strong style="color: #dc2626;">[${c_m.tuan_triet}]</strong>` : '';
      
      const m_luu = [];
      [...(c_m.luu_tinh || []), ...c_m.cat_tinh, ...c_m.hung_tinh].forEach(s => {
        if (s.is_luu || s.name.startsWith("L.")) {
          const nm = s.name.startsWith("L.") ? s.name : `L.${s.name}`;
          if (!m_luu.includes(nm)) m_luu.push(nm);
        }
      });
      const m_luu_str = m_luu.length > 0 ? `<br><span style="color: #6d28d9; font-weight: bold; font-size: 0.78rem;">⚡ ${m_luu.join(", ")}</span>` : '';

      // XC stars
      const xc_chinh = c_xc.chinh_tinh.map(s => s.name).join(", ") || "Vô Chính Diệu";
      const xc_luu = [];
      [...(c_xc.luu_tinh || []), ...c_xc.cat_tinh, ...c_xc.hung_tinh].forEach(s => {
        if (s.is_luu || s.name.startsWith("L.")) {
          const nm = s.name.startsWith("L.") ? s.name : `L.${s.name}`;
          if (!xc_luu.includes(nm)) xc_luu.push(nm);
        }
      });
      const xc_luu_str = xc_luu.length > 0 ? ` <span style="color: #dc2626; font-size: 0.76rem;">(${xc_luu.join(",")})</span>` : '';

      // TH stars
      const th1_name = `${c_th[0].name} (${c_th[0].chi})`;
      const th2_name = `${c_th[1].name} (${c_th[1].chi})`;
      const th_luus = [];
      [c_th[0], c_th[1]].forEach(th => {
        [...(th.luu_tinh || []), ...th.cat_tinh, ...th.hung_tinh].forEach(s => {
          if (s.is_luu || s.name.startsWith("L.")) {
            const nm = s.name.startsWith("L.") ? s.name : `L.${s.name}`;
            if (!th_luus.includes(nm)) th_luus.push(nm);
          }
        });
      });
      const th_luu_str = th_luus.length > 0 ? `<br><span style="color: #b45309; font-size: 0.76rem; font-weight: bold;">Hội: ${th_luus.join(", ")}</span>` : '';

      // NH stars
      const nh_str = `<strong>${c_nh.name}</strong> (${c_nh.chi})<br><span style="font-size: 0.76rem; color: #64748b;">${c_m.chi} hợp ${c_nh.chi}</span>`;

      let statusBadge = `<span style="background: #ecfdf5; color: #047857; padding: 2px 8px; border-radius: 4px; font-weight: bold; font-size: 0.78rem;">Thuận lợi</span>`;
      if (m_scores.overall < 3) {
        statusBadge = `<span style="background: #fff1f2; color: #be123c; padding: 2px 8px; border-radius: 4px; font-weight: bold; font-size: 0.78rem;">Thận trọng</span>`;
      } else if (m_scores.career >= 4 && m_scores.wealth >= 4) {
        statusBadge = `<span style="background: #fefce8; color: #b45309; padding: 2px 8px; border-radius: 4px; font-weight: bold; font-size: 0.78rem;">Đột phá</span>`;
      }

      const isCurrent = (m === selectedMonth);
      tableHtml += `
        <tr style="${isCurrent ? 'background: #fffbeb; font-weight: 600;' : ''}" onclick="renderDedicatedMonthlyTab(${m})" style="cursor: pointer;">
          <td style="text-align: center;"><strong>Tháng ${m}</strong></td>
          <td><strong>${c_m.name}</strong> (${c_m.can} ${c_m.chi})<br><span style="font-size: 0.8rem; color: #8b0000;">${m_chinh}</span> ${m_tt}${m_luu_str}</td>
          <td><strong>${c_xc.name}</strong> (${c_xc.chi})<br><span style="font-size: 0.78rem; color: #475569;">${xc_chinh}</span>${xc_luu_str}</td>
          <td>${th1_name} & ${th2_name}${th_luu_str}</td>
          <td>${nh_str}</td>
          <td style="text-align: center;">
            <div style="font-size: 0.75rem; color: #475569;">Công danh: ${getStarRatingHtml(m_scores.career)}</div>
            <div style="font-size: 0.75rem; color: #475569; margin-top: 2px;">Tài lộc: ${getStarRatingHtml(m_scores.wealth)}</div>
          </td>
          <td style="text-align: center;">${statusBadge}</td>
        </tr>
      `;
    }
    tableHtml += `</tbody>`;
    matrixTable.innerHTML = tableHtml;
  }
}

function updateDedicatedDailyView() {
  const selDay = document.getElementById("sel-dedicated-han-day");
  const displayBox = document.getElementById("dedicated-daily-display-box");
  if (!selDay || !displayBox) return;

  const day = Number(selDay.value) || 1;
  const month = currentDedicatedMonth || 1;
  const chiList = ["Tý", "Sửu", "Dần", "Mão", "Thìn", "Tỵ", "Ngọ", "Mùi", "Thân", "Dậu", "Tuất", "Hợi"];
  
  const monthChamber = tuviData.chambers.find(c => c.nguyet_han === month) || tuviData.chambers[(month - 1) % 12];
  const nguyetChiIdx = chiList.indexOf(monthChamber.chi);
  const nhatChiIdx = (nguyetChiIdx + day - 1) % 12;
  const nhatChamber = tuviData.chambers.find(c => c.chi === chiList[nhatChiIdx]) || tuviData.chambers[0];
  
  const nhatChinh = nhatChamber.chinh_tinh.map(s => s.name).join(", ") || "Vô Chính Diệu";
  const nhatCat = nhatChamber.cat_tinh.filter(s => !s.is_luu && !s.name.startsWith("L.")).map(s => s.name).join(", ") || "Không có";
  const nhatHung = nhatChamber.hung_tinh.filter(s => !s.is_luu && !s.name.startsWith("L.")).map(s => s.name).join(", ") || "Không có";
  
  displayBox.innerHTML = `
    <strong>Mùng ${day} Tháng ${month} Âm Lịch:</strong> Nhật Hạn ngụ tại cung <strong>${nhatChamber.name} (${nhatChamber.can} ${nhatChamber.chi} - Hành ${nhatChamber.element})</strong>.
    <br>• <strong>Chính tinh:</strong> <span style="color: #8b0000; font-weight: bold;">${nhatChinh}</span> ${nhatChamber.tuan_triet ? `[${nhatChamber.tuan_triet}]` : ''}
    <br>• <strong>Cát tinh hội tụ:</strong> <span style="color: var(--color-moc);">${nhatCat}</span>
    <br>• <strong>Hung tinh chiếu:</strong> <span style="color: var(--color-hoa);">${nhatHung}</span>
    <br>• <strong>Lời khuyên trong ngày:</strong> Hành sự chủ động, giữ chữ tín trong giao tiếp, tập trung hoàn thành các công việc tồn đọng để chuẩn bị cho chu kỳ cát khí kế tiếp.
  `;
}

// Generate fallback or match-based classical readings for accordion items
function getChamberClassicalReadings(chamber) {
  const list = classicalReadingsDatabase[chamber.id] || [];
  const resides = [
    ...chamber.chinh_tinh.map(s => s.name.toUpperCase()),
    ...chamber.cat_tinh.map(s => s.name.toUpperCase()),
    ...chamber.hung_tinh.map(s => s.name.toUpperCase())
  ];
  
  let html = "";
  let matches = 0;
  
  list.forEach(item => {
    const matchesAll = item.stars.every(s => resides.includes(s));
    if (matchesAll) {
      matches++;
      const title = item.title.replace("[Chi]", chamber.chi);
      html += `
        <div class="reading-block">
          <div class="reading-title">${title}</div>
          <div class="reading-text">${item.text}</div>
          <div class="reading-source">${item.source}</div>
        </div>
      `;
    }
  });
  
  if (matches === 0) {
    const mainStarNames = chamber.chinh_tinh.map(s => s.name).join(", ");
    if (mainStarNames) {
      html += `
        <div class="reading-block">
          <div class="reading-title">Cung ${chamber.name} an tại ${chamber.chi} có chính tinh ${mainStarNames}</div>
          <div class="reading-text">Đương số chịu sự chi phối và ảnh hưởng chính của tinh hệ ${mainStarNames} tọa thủ tại bản cung, mang năng lượng đặc trưng quy định trực tiếp hoạt động của phương diện này.</div>
          <div class="reading-source">Nghiên cứu tinh mệnh học - Biên soạn tổng hợp</div>
        </div>
      `;
    } else {
      html += `
        <div class="reading-block">
          <div class="reading-title">Cung ${chamber.name} an tại ${chamber.chi} Vô Chính Diệu</div>
          <div class="reading-text">Cung vị trống trải không có chính tinh trực tiếp cai quản, dễ bị dao động và thu hút 100% năng lượng xung chiếu từ cung vị đối diện dội sang để gánh vác hoạt động.</div>
          <div class="reading-source">Nghiên cứu tinh mệnh học - Biên soạn tổng hợp</div>
        </div>
      `;
    }
  }
  
  return html;
}

// Generate general readings HTML
function generateGeneralReadingsHtml(data) {
  const p = data.personal_info;
  const chambers = data.chambers;
  
  const thanChamber = chambers.find(c => c.is_than);
  const thanCungName = thanChamber ? thanChamber.name : "";
  
  let thanExplanationTrungChau = "";
  let thanExplanationDaiDuc = "";
  if (thanCungName.toUpperCase() === "PHÚC ĐỨC") {
    thanExplanationTrungChau = "Rất biết cảm thụ và hưởng thụ cuộc sống, nặng quan niệm nhân quả và phúc đức của tổ tiên.";
    thanExplanationDaiDuc = "Khá xem trọng hưởng thụ cá nhân, tổ hợp sao cát thì có hưởng thụ, hung thì không. Tiêu tiền cho mình, để thỏa mãn chuyện vui chơi giải trí. Trường hợp hai cung Tài Phúc đều không tốt, là một đời vất vả, cuộc sống quá buồn. Trường hợp cung Tài tốt còn cung Phúc không tốt, có tiền mà không biết xài, là đầy tớ giữ tiền. Trường hợp cung Tài không tốt mà cung Phúc tốt, biết tri túc.";
  } else if (thanCungName.toUpperCase() === "MỆNH") {
    thanExplanationTrungChau = "Chủ về tính độc lập, tự lập cánh sinh, tự chịu trách nhiệm về vận mệnh cuộc đời mình.";
    thanExplanationDaiDuc = "Coi trọng sự tự lập, tự cường. Mọi sự thành bại đều tự tay làm nên, ít dựa dẫm vào thế lực bên ngoài.";
  } else if (thanCungName.toUpperCase() === "PHU THÊ") {
    thanExplanationTrungChau = "Coi trọng đời sống hôn nhân, tình cảm gia đình gắn bó, chịu ảnh hưởng lớn từ bạn đời.";
    thanExplanationDaiDuc = "Rất nặng tình cảm, coi trọng hạnh phúc lứa đôi. Mọi sự vui buồn trong cuộc sống đều gắn liền với người bạn đời.";
  } else if (thanCungName.toUpperCase() === "THIÊN DI") {
    thanExplanationTrungChau = "Thích di chuyển, đi lại nhiều, cuộc sống hướng ngoại và đi xa lập nghiệp dễ thành đạt.";
    thanExplanationDaiDuc = "Tính cách thích bay nhảy, dịch chuyển. Thích hợp đi xa làm ăn, ngoại giao gặp nhiều may mắn lành.";
  } else if (thanCungName.toUpperCase() === "QUAN LỘC") {
    thanExplanationTrungChau = "Dồn toàn tâm toàn lực cho sự nghiệp và công danh, coi công việc là mục tiêu hàng đầu cuộc sống.";
    thanExplanationDaiDuc = "Coi trọng công việc và sự nghiệp. Cả đời luôn bận rộn phấn đấu thăng tiến, lấy công danh làm niềm vui cuộc sống.";
  } else if (thanCungName.toUpperCase() === "TÀI BẠCH") {
    thanExplanationTrungChau = "Coi trọng tiền tài, thực tế và nhạy bén về tài chính, lấy của cải vật chất làm thước đo thành đạt.";
    thanExplanationDaiDuc = "Coi trọng giá trị vật chất và năng lực kiếm tiền. Thích quản lý tài chính và tích lũy tích trữ của cải chắc chắn.";
  }
  
  let laiNhanExplanation = "";
  if (p.lai_nhan_cung === "Tật Ách") {
    laiNhanExplanation = "Sức khỏe, việc học hành sẽ ảnh hưởng đến cuộc đời của mệnh tạo. 'Lai nhân cung' ở tam phương của cung điền trạch (điền, huynh, tật) là cách cục nhờ vả người khác để lập nghiệp, thuộc cung vị ở trạng thái động. Lai nhân cung không ở bốn cung mệnh, tài, quan, điền thì có lợi cho người khác như anh em, vợ chồng, con cái, cha mẹ, bạn bè.";
  } else if (p.lai_nhan_cung === "Mệnh") {
    laiNhanExplanation = "Lai nhân cung đóng tại Mệnh chủ về đương số tự lực lập nghiệp bằng thực lực của mình, số phận cát hung do chính mình định đoạt.";
  } else if (p.lai_nhan_cung === "Huynh Đệ") {
    laiNhanExplanation = "Mối quan hệ anh em có sự nợ nần nhân duyên sâu sắc, thành bại cuộc đời có sự tương trợ hoặc chịu liên đới lớn từ anh chị em trong nhà.";
  } else if (p.lai_nhan_cung === "Phu Thê") {
    laiNhanExplanation = "Hôn nhân và bạn đời ảnh hưởng cực lớn đến vận trình công danh cuộc đời, nhân duyên vợ chồng là định mệnh nghiệp quả định đoạt thành bại.";
  } else if (p.lai_nhan_cung === "Tử Tức") {
    laiNhanExplanation = "Con cái và thế hệ sau là nhân duyên nghiệp quả chi phối cuộc đời đương số, dành nhiều tâm huyết và tiền của vì con cái.";
  } else if (p.lai_nhan_cung === "Tài Bạch") {
    laiNhanExplanation = "Tiền tài kinh tế tài chính là nhân tố quyết định chi phối mạnh mẽ nhất vận trình cuộc đời, tự tay tạo lập nguồn tài chính độc lập lớn.";
  } else if (p.lai_nhan_cung === "Thiên Di") {
    laiNhanExplanation = "Môi trường bên ngoài, đi xa làm ăn xuất ngoại chi phối sâu sắc vận mệnh đương số, có số định cư lập nghiệp hiển đạt phương xa.";
  } else if (p.lai_nhan_cung === "Nô Bộc") {
    laiNhanExplanation = "Bạn bè đối tác, cấp dưới và các mối quan hệ xã giao chi phối trực tiếp định hướng và thành bại của đương số.";
  } else if (p.lai_nhan_cung === "Quan Lộc") {
    laiNhanExplanation = "Sự nghiệp học thức công danh là hạt nhân chi phối toàn bộ cuộc đời, phấn đấu hết mình để giành vị trí cao trong xã hội.";
  } else if (p.lai_nhan_cung === "Điền Trạch") {
    laiNhanExplanation = "Điền sản gia sản, nhà cửa đất đai là nhân quả tích lũy chi phối lớn cuộc đời, có số quy tụ điền sản thừa kế to lớn.";
  } else if (p.lai_nhan_cung === "Phúc Đức") {
    laiNhanExplanation = "Phúc đức dòng họ, âm phần gia tiên và đời sống tâm linh tư tưởng chi phối sâu sắc an lành nội tâm đương số.";
  } else if (p.lai_nhan_cung === "Phụ Mẫu") {
    laiNhanExplanation = "Cha mẹ và nền tảng gia đình có ảnh hưởng nhân duyên sâu sắc chi phối lớn đến sự định hình cuộc sống và học vấn thời trẻ.";
  }
  
  const weightVal = p.weight;
  const poemData = weightPoems[weightVal] || {
    poem: "Vận số bình hòa đắc ấm no\r\nMưu sự hanh thông chẳng phải lo\r\nHậu vận an nhàn hưởng phúc đức\r\nTài lộc dồi dào lộc trời cho.",
    meaning: "Cuộc đời tương đối ổn định, gặp nhiều may mắn lành và được ấm no hạnh phúc."
  };
  
  const poemHtml = poemData.poem.replace(/\r\n/g, "<br>").replace(/\n/g, "<br>");
  
  return `
    <div class="reading-block">
      <div class="reading-title" style="color: var(--color-gold); font-size: 1.05rem; font-weight:700;">Cung Thân cư ở cung ${thanCungName.charAt(0) + thanCungName.slice(1).toLowerCase()}</div>
      <div class="reading-text">${thanExplanationTrungChau}</div>
      <div class="reading-source">Trung Châu tử vi đẩu số - Tứ Hóa Phái - Nguyễn Anh Vũ dịch</div>
    </div>
    
    <div class="reading-block">
      <div class="reading-title" style="color: var(--color-gold); font-size: 1.05rem; font-weight:700;">Cung Thân cư ở cung ${thanCungName.charAt(0) + thanCungName.slice(1).toLowerCase()}</div>
      <div class="reading-text">${thanExplanationDaiDuc}</div>
      <div class="reading-source">Tử vi đẩu số tinh hoa tập thành - Đại Đức Sơn Nhân</div>
    </div>
    
    <div class="reading-block">
      <div class="reading-title" style="color: var(--color-gold); font-size: 1.05rem; font-weight:700;">Lai Nhân Cung ở cung ${p.lai_nhan_cung}</div>
      <div class="reading-text">${laiNhanExplanation}</div>
      <div class="reading-source">Trung Châu tử vi đẩu số - Tứ Hóa Phái - Nguyễn Anh Vũ dịch</div>
    </div>
    
    <div class="reading-block" style="border-bottom: none; margin-bottom: 0; padding-bottom: 0;">
      <div class="reading-title" style="color: var(--color-gold); font-size: 1.05rem; font-weight:700;">Cân Xương Tính Số: Số ${weightVal}</div>
      <div class="reading-text" style="font-size: 1rem; font-style: italic; text-align: center; margin: 15px 0; font-family: 'Playfair Display', Georgia, serif; line-height: 1.8; letter-spacing: 0.5px; color: var(--color-text-primary);">
        ${poemHtml}
      </div>
      <div class="reading-text" style="border-left: 3px solid var(--color-gold); padding-left: 12px; margin-top: 12px; font-size: 0.9rem;">
        <strong>Bình giải cốt cách:</strong> ${poemData.meaning}
      </div>
    </div>
  `;
}

// Generate 12 chambers accordion HTML
function generateChambersAccordionHtml(data) {
  const chambers = data.chambers;
  const order = ["menh", "phu_mau", "phuc_duc", "dien_trach", "quan_loc", "no_boc", "thien_di", "tat_ach", "tai_bach", "tu_tuc", "phu_the", "huynh_de"];
  
  let html = "";
  
  order.forEach(id => {
    const chamber = chambers.find(c => c.id === id);
    if (!chamber) return;
    
    let chamberLabel = "";
    if (id === "menh") chamberLabel = "Cung Mệnh (Luận về con người)";
    else if (id === "phu_mau") chamberLabel = "Cung Phụ Mẫu (Luận về cha mẹ)";
    else if (id === "phuc_duc") chamberLabel = "Cung Phúc Đức (Luận về họ hàng)";
    else if (id === "dien_trach") chamberLabel = "Cung Điền Trạch (Luận về nhà đất)";
    else if (id === "quan_loc") chamberLabel = "Cung Quan Lộc (Luận về công danh)";
    else if (id === "no_boc") chamberLabel = "Cung Nô Bộc (Luận về bạn bè)";
    else if (id === "thien_di") chamberLabel = "Cung Thiên Di (Luận về xuất hành)";
    else if (id === "tat_ach") chamberLabel = "Cung Tật Ách (Luận về bệnh tật)";
    else if (id === "tai_bach") chamberLabel = "Cung Tài Bạch (Luận về tiền bạc)";
    else if (id === "tu_tuc") chamberLabel = "Cung Tử Tức (Luận về con cái)";
    else if (id === "phu_the") chamberLabel = "Cung Phu Thê (Luận về vợ chồng)";
    else if (id === "huynh_de") chamberLabel = "Cung Huynh Đệ (Luận về anh/chị/em)";
    
    if (chamber.is_than) {
      chamberLabel += " - Thân Cư";
    }
    
    const readingsHtml = getChamberClassicalReadings(chamber);
    
    html += `
      <div class="accordion-item">
        <div class="accordion-header" onclick="toggleAccordion('acc-${id}')">
          <span>◆ ${chamberLabel}</span>
          <span class="accordion-arrow" id="arrow-acc-${id}">Xem chi tiết ▾</span>
        </div>
        <div id="content-acc-${id}" class="accordion-content">
          ${readingsHtml}
        </div>
      </div>
    `;
  });
  
  return html;
}

// Generate all readings on UI
function generateDetailedReadings() {
  const generalBody = document.getElementById("general-readings-body");
  const chambersBody = document.getElementById("chambers-readings-body");
  const tuantrietBody = document.getElementById("tuantriet-readings-body");
  
  // Generate Đại vận & Tiểu vận grids
  generateLimitsHtml();
  
  if (!tuviData || !tuviData.personal_info) {
    if (generalBody) generalBody.innerHTML = `<p style="text-align: center; color: var(--color-text-secondary); font-style: italic;">Vui lòng nhập thông tin lập lá số để xem luận giải tổng quan.</p>`;
    if (chambersBody) chambersBody.innerHTML = `<p style="text-align: center; color: var(--color-text-secondary); font-style: italic;">Vui lòng nhập thông tin lập lá số để xem chi tiết bình giải 12 cung vị.</p>`;
    if (tuantrietBody) tuantrietBody.innerHTML = `<p style="text-align: center; color: var(--color-text-secondary); font-style: italic;">Vui lòng nhập thông tin lập lá số để xem chuyên đề Tuần - Triệt.</p>`;
    return;
  }
  
  if (generalBody) {
    generalBody.innerHTML = generateGeneralReadingsHtml(tuviData);
  }
  if (chambersBody) {
    chambersBody.innerHTML = generateChambersAccordionHtml(tuviData);
  }
  if (tuantrietBody) {
    tuantrietBody.innerHTML = generateGlobalTuanTrietHtml(tuviData);
  }
}



