function getYearCanChi(year) {
  const canList = ["Canh", "Tân", "Nhâm", "Quý", "Giáp", "Ất", "Bính", "Đinh", "Mậu", "Kỷ"];
  const chiList = ["Thân", "Dậu", "Tuất", "Hợi", "Tý", "Sửu", "Dần", "Mão", "Thìn", "Tỵ", "Ngọ", "Mùi"];
  return canList[year % 10] + " " + chiList[year % 12];
}

// Generate the limit readings blocks
function getLimitReadingsHtml(chamber) {
  const resides = [
    ...chamber.chinh_tinh.map(s => s.name.toUpperCase()),
    ...chamber.cat_tinh.map(s => s.name.toUpperCase()),
    ...chamber.hung_tinh.map(s => s.name.toUpperCase())
  ];
  if (chamber.tuan_triet) {
    if (chamber.tuan_triet.includes("Tuần")) resides.push("TUẦN");
    if (chamber.tuan_triet.includes("Triệt")) resides.push("TRIỆT");
  }
  
  let html = "";
  let matches = 0;
  
  limitReadingsDatabase.forEach(item => {
    const matchesAll = item.stars.every(s => resides.includes(s));
    if (matchesAll) {
      matches++;
      html += `
        <div class="reading-block" style="margin-bottom: 15px; padding-bottom: 12px; border-bottom: 1px dashed rgba(255,255,255,0.05);">
          <div class="reading-title" style="color: #3b82f6; font-size: 0.95rem; font-weight: 700; margin-bottom: 6px;">
            Đại vận/Tiểu vận ở cung ${chamber.name} (tại ${chamber.chi}) có các sao ${item.stars.map(s => s.toLowerCase()).join(", ")}
          </div>
          <div class="reading-text" style="font-size: 0.88rem; line-height: 1.5; color: var(--color-text-primary); text-align: justify; margin-bottom: 4px;">
            ${item.text}
          </div>
          <div class="reading-source" style="font-size: 0.8rem; color: var(--color-text-secondary); text-align: right; font-style: italic;">
            ${item.source}
          </div>
        </div>
      `;
    }
  });
  
  if (matches === 0) {
    const mainStarNames = chamber.chinh_tinh.map(s => s.name).join(", ");
    html += `
      <div class="reading-block" style="border: none; margin: 0; padding: 0;">
        <div class="reading-title" style="color: #3b82f6; font-size: 0.95rem; font-weight: 700;">Hạn đến cung ${chamber.name} tại ${chamber.chi}</div>
        <div class="reading-text" style="font-size: 0.88rem; line-height: 1.5; color: var(--color-text-primary);">
          Vận trình của bạn dịch chuyển tới cung ${chamber.name} chứa cát hung tinh ${mainStarNames || "Vô chính diệu"}. Đây là giai đoạn cần củng cố nội lực ổn định hành sự.
        </div>
        <div class="reading-source">Nghiên cứu tinh mệnh học - Biên soạn tổng hợp</div>
      </div>
    `;
  }
  
  return html;
}

// Click callback for Đại Vận
function selectDaiVan(startAge) {
  // Highlight active button
  const buttons = document.querySelectorAll("#daivan-grid .limit-btn");
  buttons.forEach(btn => btn.classList.remove("active"));
  
  const activeBtn = Array.from(buttons).find(btn => btn.dataset.age == startAge);
  if (activeBtn) activeBtn.classList.add("active");
  
  // Find corresponding chamber
  const chambers = tuviData.chambers;
  const chamber = chambers.find(c => c.dai_han === startAge);
  const display = document.getElementById("daivan-display");
  if (!chamber || !display) return;
  
  const endAge = startAge + 9;
  const readingsHtml = getLimitReadingsHtml(chamber);
  
  // 1. Calculate projected aspect stars
  const aspectHtml = getAspectInfluenceHtml(chamber);
  
  display.innerHTML = `
    <div style="margin-bottom: 12px; border-bottom: 2px solid var(--color-gold); padding-bottom: 8px;">
      <strong style="color: var(--color-gold); font-size: 1.05rem;">Đại vận ${startAge} - ${endAge} tuổi tại cung ${chamber.name} (ở ${chamber.chi})</strong>
    </div>
    <div style="max-height: 450px; overflow-y: auto; padding-right: 5px;">
      <div style="margin-bottom: 15px;">
        <strong style="color: #60a5fa; font-size: 0.95rem; display: block; margin-bottom: 8px;">★ BẢN CUNG TỌA THỦ (CÁC SAO ĐÓNG TẠI CUNG ĐẠI VẬN):</strong>
        ${readingsHtml}
      </div>
      ${aspectHtml}
    </div>
  `;
}

// Click callback for Tiểu Vận
function selectTieuVan(age) {
  // Highlight active button
  const buttons = document.querySelectorAll("#tieuvan-grid .limit-btn");
  buttons.forEach(btn => btn.classList.remove("active"));
  
  const activeBtn = Array.from(buttons).find(btn => btn.dataset.age == age);
  if (activeBtn) activeBtn.classList.add("active");
  
  const display = document.getElementById("tieuvan-display");
  if (!display) return;
  
  const p = tuviData.personal_info;
  const chambers = tuviData.chambers;
  
  // Locate target chamber using Small Limit formula
  const chiNam = p.birth_year_lunar.split(" ")[1]; // e.g. "Hợi"
  const chiList = ["Tý", "Sửu", "Dần", "Mão", "Thìn", "Tỵ", "Ngọ", "Mùi", "Thân", "Dậu", "Tuất", "Hợi"];
  
  let startChi = "Sửu";
  if (["Hợi", "Mão", "Mùi"].includes(chiNam)) startChi = "Sửu";
  else if (["Dần", "Ngọ", "Tuất"].includes(chiNam)) startChi = "Tuất";
  else if (["Thân", "Tý", "Thìn"].includes(chiNam)) startChi = "Thìn";
  else if (["Tỵ", "Dậu", "Sửu"].includes(chiNam)) startChi = "Mùi";
  
  const startIdx = chiList.indexOf(startChi);
  const dir = p.gender && p.gender.includes("Nữ") ? -1 : 1;
  const tieuVanIdx = (((startIdx + dir * (age - 1)) % 12) + 12) % 12;
  const targetChamber = chambers.find(c => c.chi === chiList[tieuVanIdx]);
  
  if (!targetChamber) return;
  
  const targetYear = p.birth_year_solar + age - 1;
  const yearCanChi = getYearCanChi(targetYear);
  const readingsHtml = getLimitReadingsHtml(targetChamber);
  
  // 1. Calculate projected aspect stars
  const aspectHtml = getAspectInfluenceHtml(targetChamber);
  
  // 2. Calculate annual Luu Tinh for targetYear
  const annualLuuMap = calculateAnnualLuuTinh(targetYear);
  const luuTinhList = annualLuuMap[targetChamber.chi] || [];
  
  let luuHtml = "";
  if (luuTinhList.length > 0) {
    let luuItems = "";
    luuTinhList.forEach(lt => {
      const meaning = luuTinhMeanings[lt] || "Lưu tinh niên hạn chi phối thời vận cát hung.";
      luuItems += `
        <div style="margin-bottom: 8px; font-size: 0.85rem; line-height: 1.4;">
          <span style="color: #ef4444; font-weight: 700;">• Sao ${lt}:</span> ${meaning}
        </div>
      `;
    });
    
    luuHtml = `
      <div style="margin-top: 15px; border-top: 1px dashed rgba(255,255,255,0.1); padding-top: 15px; margin-bottom: 15px;">
        <strong style="color: #f87171; font-size: 0.95rem; display: block; margin-bottom: 8px;">★ CÁC SAO LƯU HẠN NĂM (SAO LƯU ĐÓNG TẠI CUNG TIỂU VẬN):</strong>
        <div style="padding: 10px; background: rgba(239,68,68,0.03); border-radius: 6px; border: 1px solid rgba(239,68,68,0.1);">
          ${luuItems}
        </div>
      </div>
    `;
  } else {
    luuHtml = `
      <div style="margin-top: 15px; border-top: 1px dashed rgba(255,255,255,0.1); padding-top: 15px; margin-bottom: 15px;">
        <strong style="color: #f87171; font-size: 0.95rem; display: block; margin-bottom: 4px;">★ CÁC SAO LƯU HẠN NĂM (SAO LƯU ĐÓNG TẠI CUNG TIỂU VẬN):</strong>
        <div style="font-size: 0.85rem; color: var(--color-text-secondary); font-style: italic;">Không có sao lưu chính nào đóng tại cung hạn này trong năm nay.</div>
      </div>
    `;
  }
  
  display.innerHTML = `
    <div style="margin-bottom: 12px; border-bottom: 2px solid var(--color-gold); padding-bottom: 8px;">
      <strong style="color: var(--color-gold); font-size: 1.05rem;">Tiểu vận năm ${age} tuổi (${yearCanChi}) tại cung ${targetChamber.name} (ở ${targetChamber.chi})</strong>
    </div>
    <div style="max-height: 450px; overflow-y: auto; padding-right: 5px;">
      <div style="margin-bottom: 15px;">
        <strong style="color: #60a5fa; font-size: 0.95rem; display: block; margin-bottom: 8px;">★ BẢN CUNG TỌA THỦ (CÁC SAO ĐÓNG TẠI CUNG TIỂU VẬN):</strong>
        ${readingsHtml}
      </div>
      ${luuHtml}
      ${aspectHtml}
    </div>
  `;
}

// Generate Đại Vận and Tiểu Vận grids and content
function generateLimitsHtml() {
  const daivanGrid = document.getElementById("daivan-grid");
  const tieuvanGrid = document.getElementById("tieuvan-grid");
  
  if (!daivanGrid || !tieuvanGrid || !tuviData || !tuviData.personal_info) return;
  
  const p = tuviData.personal_info;
  const chambers = tuviData.chambers;
  
  // 1. Generate Đại Vận Grid
  const startAge = Math.min(...chambers.map(c => c.dai_han));
  let daivanHtml = "";
  for (let i = 0; i < 12; i++) {
    const ageVal = startAge + i * 10;
    const endAge = ageVal + 9;
    daivanHtml += `<button class="limit-btn" data-age="${ageVal}" onclick="selectDaiVan(${ageVal})">Đại vận ${ageVal}-${endAge} tuổi</button>`;
  }
  daivanGrid.innerHTML = daivanHtml;
  
  // 2. Generate Tiểu Vận Grid
  let tieuvanHtml = "";
  for (let ageVal = 13; ageVal <= 70; ageVal++) {
    const targetYear = p.birth_year_solar + ageVal - 1;
    const yearCanChi = getYearCanChi(targetYear);
    tieuvanHtml += `<button class="limit-btn" data-age="${ageVal}" onclick="selectTieuVan(${ageVal})">${ageVal} tuổi - ${yearCanChi}</button>`;
  }
  tieuvanGrid.innerHTML = tieuvanHtml;
  
  // 3. Auto-select current limits based on current age
  const currentAge = p.age; // e.g. 32
  
  // Find current Đại Vận start age
  const currentDaiVanChamber = chambers.find(c => currentAge >= c.dai_han && currentAge <= (c.dai_han + 9));
  const currentDaiVanStart = currentDaiVanChamber ? currentDaiVanChamber.dai_han : startAge;
  
  selectDaiVan(currentDaiVanStart);
  selectTieuVan(currentAge);
}



