function getGodColor(godName) {
  if (godName === "Thương Quan" || godName === "Thất Sát" || godName === "Kiếp Tài") {
    return "#ef4444";
  }
  if (godName === "Tỷ Kiên") {
    return "var(--color-text-secondary)";
  }
  return "var(--color-moc)";
}
